      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有大语言模型训练数据归因方法，要么重复重训算力开销极高，要么梯度近似成本高且依赖局部近似。",
      "method": "提出STRIDE框架，在激活空间建模训练数据的功能影响，将归因建模为稀疏恢复问题，学习轻量引导算子计算样本影响力。",
      "contribution": "提出的STRIDE在大模型预训练归因达到SOTA，速度比现有最优方法快13倍，可支撑多个下游应用。",
      "limitations": "摘要未提及",
