      "title": "Visual Instruction Tuning Aligns Modalities through Abstraction",
      "title_zh": "视觉指令微调通过抽象实现模态对齐",
      "authors": [
        "Luis Palacios",
        "Lorenzo Basile",
        "Diego Doimo",
        "Alberto Cazzaniga"
      ],
      "url": "http://arxiv.org/abs/2606.03871v1",
