      "title": "Expert-Aware Causal Tracing of Factual Recall in Sparse MoE Language Models",
      "title_zh": "稀疏混合专家语言模型中事实回忆的专家感知因果追踪",
      "authors": [
        "Yuetian Lu",
        "Ali Modarressi",
        "Yihong Liu",
        "Hinrich Schütze"
      ],
      "url": "http://arxiv.org/abs/2606.03780v1",
