      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有大语言模型特征蒸馏依赖直接表征对齐，未考虑表征维度的相关性由其对模型输出的影响决定",
      "method": "基于教师模型的功能几何视角，提出仅迁移输出贡献主导方向，得到架构无关无参数的Flex-KD蒸馏方法",
      "contribution": "提出功能视角的蒸馏分析框架，提出Flex-KD方法，在多类NLP基准上性能优于现有蒸馏方法",
      "limitations": "摘要未提及",
