      "direction_name": "编辑可靠性与行为控制",
      "week": "2026-W24",
      "title": "Guide Me Out: A Framework to Benchmark VLM Operators Communication in Crisis Scenarios",
      "title_zh": "Guide Me Out：危机场景中VLM算子通信的基准测试框架",
      "authors": [
        "Giacomo Gonella",
        "Stefano Menini",
        "Marco Guerini"
      ],
      "url": "http://arxiv.org/abs/2606.09428v1",
