      "title": "Harnessing Textual Refusal Directions for Multimodal Safety",
      "title_zh": "利用文本拒绝方向实现多模态安全性",
      "authors": [
        "Moreno D'Incà",
        "Massimiliano Mancini",
        "Nicu Sebe"
      ],
      "url": "http://arxiv.org/abs/2606.31876v1",
