      "direction_name": "编辑可靠性与行为控制",
      "week": "2026-W28",
      "title": "Faithfulness to Refusal: A Causal Audit of Neuron Selectors",
      "title_zh": "《对拒绝行为的忠实性：神经元选择器的因果审计》",
      "authors": [
        "Ananth Eswar",
        "Pratinav Seth",
        "Utsav Avaiya",
        "Vinay Kumar Sankarapu"
      ],
      "url": "http://arxiv.org/abs/2607.05355v1",
