      "title": "PRISM Edit: One Vector for All Temporal Answers",
      "title_zh": "PRISM Edit：面向全时序答案的单向量编辑方法",
      "authors": [
        "Chen Huang",
        "Qi Zheng",
        "Ruiqin Zheng",
        "Long Zeng",
        "Yuantong Xu"
      ],
      "url": "http://arxiv.org/abs/2607.11327v1",
