      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "LoRA微调会产生引发灾难性遗忘的入侵者维度，此前尚无理论可逐层预测其出现阈值。",
      "method": "基于预训练权重的谱，通过矩形尖峰变形变换推导逐层临界更新强度阈值，刻画更新谱特征。",
      "contribution": "推导了无拟合参数的入侵者出现阈值谱定律，得到的尖峰预算规则可无任务成本降低62%遗忘。",
      "limitations": "摘要未提及",
      "key_finding": "跨越阈值的层而非更新幅度导致遗忘，定律区分有无入侵者层平均AUC为0.89，82%层阈值定位误差在2倍内。",
      "theme": "LoRA微调可靠性",
      "method_family": "model steering",
      "agent_setting": "非Agent论文",
      "control_mechanism": "通过推导LoRA微调入侵者维度的出现阈值，提出尖峰预算规则约束阈值穿越，无任务性能损失地减少遗忘。",
      "evaluation_environment": "WikiText-2、多类Transformer族模型，指标为AUC、困惑度、遗忘降低比例",
      "evaluation_signal": "82%层阈值定位误差在2倍内，区分入侵者层平均AUC达0.89，可降低最脆弱模型62%遗忘且无任务成本。",
      "failure_mode": "LoRA微调更新过阈值产生入侵者维度，引发灾难性遗忘",
