      "title": "Emergent Latent-State Computation under Stochastic Volatility",
      "title_zh": "随机波动率下的涌现潜态计算",
      "authors": [
        "Xiaoyu Huang",
        "Lulu Wang"
      ],
      "url": "http://arxiv.org/abs/2607.25459v1",
      "pdf_url": "https://arxiv.org/pdf/2607.25459v1",
