      "title": "DoTime: A Synthetic Benchmark Generator for Interventional and Counterfactual Time Series",
      "title_zh": "DoTime：面向干预与反事实时间序列的合成基准生成器",
      "authors": [
        "Dennis Thumm",
        "Billy Tim Anthony",
        "Ying Chen"
      ],
      "url": "http://arxiv.org/abs/2607.27263v1",
