      "title": "A Fortran General-Purpose Transpiler: Proof of Concept",
      "title_zh": "Fortran通用转译器：概念验证",
      "authors": [
        "Shivamshan Sivanesan",
        "Kazem Ardaneh"
      ],
      "url": "http://arxiv.org/abs/2608.00130v1",
