      "title": "RigidBench: Evaluating Rigid-Body Physics in Video Generation Models",
      "title_zh": "RigidBench：评测视频生成模型中的刚体物理能力",
      "authors": [
        "Swarnim Jain",
        "Shangzhe Wu"
      ],
      "url": "http://arxiv.org/abs/2608.15555v1",
      "pdf_url": "https://arxiv.org/pdf/2608.15555v1",
