      "title": "Interpreting and Steering for Safe and Correct Code Generation",
      "title_zh": "面向安全正确代码生成的解释与引导",
      "authors": [
        "Hao Yan",
        "Ziyu Yao"
      ],
      "url": "http://arxiv.org/abs/2608.30025v1",
      "pdf_url": "https://arxiv.org/pdf/2608.30025v1",
