      "week": "2026-W37",
      "title": "From Vision to Language: Investigating Causal Information Flow in Multimodal Decision-Making",
      "title_zh": "从视觉到语言：多模态决策中的因果信息流研究",
      "authors": [
        "Davide Testa",
        "Hugh Mee Wong",
        "Alessandro Lenci",
        "Bernardo Magnini",
        "Albert Gatt"
      ],
      "url": "http://arxiv.org/abs/2609.05149v1",
      "pdf_url": "https://arxiv.org/pdf/2609.05149v1",
