      "title": "Record Grouping Controls Evidence Weight in Language Models",
      "title_zh": "记录分组控制语言模型中的证据权重",
      "authors": [
        "Zhongxuan Liu",
        "Sicheng Zhou",
        "Hongzhi Wang"
      ],
      "url": "http://arxiv.org/abs/2609.08698v1",
