      "title": "JuryFlow: Disagreement-Guided Human-in-the-Loop Multi-Agent Evaluation",
      "title_zh": "提取失败",
      "authors": [
        "Mufeng Yang",
        "Junwei Yu",
        "Yepeng Ding"
      ],
      "url": "http://arxiv.org/abs/2609.40103v1",
      "pdf_url": "https://arxiv.org/pdf/2609.40103v1",
