      "week": "2026-W41",
      "title": "EgoVoice: Proactive Spoken Assistance from Egocentric Multimodal Streams",
      "title_zh": "提取失败",
      "authors": [
        "Heeseung Kim"
      ],
      "url": "http://arxiv.org/abs/2610.12248v1",
      "pdf_url": "https://arxiv.org/pdf/2610.12248v1",
