      "agent_setting": "tool-use",
      "control_mechanism": "通过设置无工具版本、纯文本推理器等不同对比组，开展消融实验评测工具调用的实际能力增益。",
      "evaluation_environment": "真实世界理解、OCR、图表理解、数学推理四类任务",
      "evaluation_signal": "关注工具接入后的性能提升幅度、生成token成本、仅工具可解决问题的占比等核心指标。",
      "failure_mode": "现有评测误将工具可用性等同于Agent实际能力扩展",
      "reliability_risk": "现有工具增强Agent的能力增益被夸大，可能误导工业界Agent工具化研发方向。",
      "industrial_relevance": "high",
