      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有自主智能体基准未评估不适宜行动场景下的弃权能力，存在固有合规偏差问题",
      "method": "提出需弃权场景的三缺口分类法，设计弃权评估协议，采用运行时强制弃权机制测试",
      "contribution": "明确合规偏差来源，构建弃权感知基准分类框架，提出评估指标，验证安全可用性权衡可调节",
      "limitations": "本研究属于初步工作，提出的分类框架与评估指标有待进一步完善验证",
      "key_finding": "运行时强制弃权机制最高阻断89.2%危险动作，授权场景可用性达87.5%，安全-可用性权衡可调节而非固有",
      "theme": "智能体弃权评测",
      "method_family": "evaluation/benchmark",
      "agent_setting": "通用自主智能体安全任务",
      "control_mechanism": "通过提出新的弃权评估框架引导改进智能体行为，采用运行时强制机制约束不安全动作",
      "evaluation_environment": "144个企业智能体场景，指标为安全率、可用性率、知情拒绝率",
      "evaluation_signal": "在5个模型族144个场景测试，得到危险动作最高阻断率89.2%、授权场景可用性87.5%的结果",
      "failure_mode": "合规偏差：无论是否满足安全前提，智能体都倾向于推进执行动作",
