      "citation_count": 0,
      "venue": "",
      "venue_year": "",
      "venue_type": "",
      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有静态搜索基准混淆智能体预存知识与搜索能力，无法准确衡量搜索智能体的真实搜索能力。",
      "method": "通过三项诊断分析搜索智能体的内在知识依赖，构建全新的时效性搜索基准LiveBrowseComp。",
      "contribution": "发现搜索智能体普遍存在内在知识依赖，提出可准确评估搜索能力的新基准LiveBrowseComp。",
      "limitations": "摘要未提及",
