      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "当前奖励评估依赖多种异构评估标准，尚未存在能够整合各类评估证据的统一机制。",
      "method": "提出Skill-RM统一框架，将奖励建模定义为可复用奖励评估技能的执行，用统一接口调度异构资源动态聚合证据。",
      "contribution": "提出统一异构奖励评估的Skill-RM框架，在多个奖励基准和下游任务中性能稳定优于传统裁判基线。",
      "limitations": "摘要未提及",
      "key_finding": "Skill-RM通过对异构证据的策略性动态调度，在最优N选和强化学习任务中稳定优于传统裁判基线。",
      "theme": "技能奖励建模",
      "method_family": "reward learning",
      "agent_setting": "single-agent",
      "control_mechanism": "通过将奖励计算建模为可复用Agent技能执行，提供统一接口调度异构评估证据，动态调整评估过程提升奖励一致性。",
      "evaluation_environment": "奖励基准、最优N选任务、强化学习下游任务",
      "evaluation_signal": "Skill-RM在奖励基准和下游的最优N选、强化学习任务中，性能均稳定优于传统裁判基线方法。",
      "failure_mode": "异构奖励评估标准难以统一整合，传统静态评估一致性、透明度不足",
      "reliability_risk": "未验证大规模工业场景下动态证据调度的工程开销，跨场景通用性未得到充分验证。",
      "industrial_relevance": "high",
