      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有智能体安全防御依赖经验语义护栏与概率仲裁，面对复杂攻击无法提供确定性的安全下界。",
      "method": "基于逻辑推理基本限制提出智能体安全新范式，设计带神经符号隔离架构的ePCA框架，要求意图形式化为一阶逻辑约束。",
      "contribution": "提供显式系统假设下的条件形式基础，给出智能体底层防御工程范式，实验实现零攻击成功率与零误报。",
      "limitations": "摘要未提及",
      "key_finding": "该论文提出的形式验证机制，在所有测试场景下实现零攻击成功率、零误报率，同时保持极低的计算延迟。",
      "theme": "智能体安全护栏",
      "method_family": "agent harness",
      "agent_setting": "tool-use",
      "control_mechanism": "提出ePCA护栏框架，采用神经符号隔离架构，要求执行动作前将意图形式化为一阶逻辑约束，通过形式验证控制行为。",
      "evaluation_environment": "宏观二维动态对抗系统、微观二维动态对抗系统，评测指标含攻击成功率、误报率、计算延迟",
      "evaluation_signal": "在所有测试对抗场景中实现了零攻击成功率、零误报率，同时计算延迟极低，安全防护性能十分出色。",
      "failure_mode": "现有语义护栏面对复杂语义符号解耦攻击无法提供确定性安全保障",
      "reliability_risk": "安全结论仅在给定显式系统假设下成立，实际场景不符合假设时，安全性无法得到保证。",
      "industrial_relevance": "high",
