      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有工具使用LLM Agent的越狱攻防均假设防御者可见连续对话，忽略实际部署中工件溯源缺失的安全漏洞。",
      "method": "提出上下文断裂分解（CFD）攻击系列，利用工件溯源缺口，通过分散的无害动作延迟组合触发越狱。",
      "contribution": "定义了工具Agent部署的溯源缺口失效模式，提出CFD攻击，相比SOTA越狱成功率最高提升28.3个百分点。",
      "limitations": "摘要未提及",
      "key_finding": "利用工件溯源缺口的CFD攻击，在Agent越狱基准上相比现有SOTA基线，成功率最高提升28.3个百分点。",
      "theme": "工具Agent安全",
      "method_family": "unlearning/safety",
      "agent_setting": "tool-use",
      "control_mechanism": "提出溯源谱系标记的可验证缓解方向，通过追踪工件来源防御工具Agent的跨步骤延迟越狱。",
      "evaluation_environment": "Agent系统越狱基准，评测指标为越狱成功率",
      "evaluation_signal": "CFD攻击在Agent系统越狱基准上表现优于现有SOTA基线，成功率最高提升28.3个百分点，可绕过强单轮防御。",
      "failure_mode": "工件溯源缺失导致跨步骤分散有害组合无法被现有越狱防御检测",
      "reliability_risk": "现有工业界工具Agent管线大多未追踪工件溯源，普遍存在被此类隐身多步攻击攻破的隐患。",
      "industrial_relevance": "high",
