      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "针对MCP标准化自主agent工具调用后，错误处理循环这一未被关注的提示注入攻击面问题。",
      "method": "提出基于突变的漏洞分析框架VATS，从七个维度系统性演化对抗payload，注入错误路径利用隐式权威实现攻击。",
      "contribution": "发现错误消息隐式权威可绕过安全防护，提出VATS框架，验证该攻击可将间接提示注入成功率提升三倍。",
      "limitations": "现有生产框架护栏仅能缓解该漏洞，模型层固有易感性仍会给定制agent工作流带来系统性风险。",
      "key_finding": "将指令夹在错误上下文的结构定位是最有效攻击向量，该攻击可将间接提示注入成功率提升三倍，最高达100%。",
      "theme": "工具调用安全",
      "method_family": "unlearning/safety",
      "agent_setting": "tool-use",
      "control_mechanism": "通过系统突变在七个维度演化对抗payload，注入工具错误处理路径，利用错误消息隐式权威绕开agent安全防护。",
      "evaluation_environment": "Gemini 3.1 Pro等四款前沿大模型，可控对抗评测环境，指标为攻击合规率",
      "evaluation_signal": "在四款前沿大模型的可控评测中，该错误路径注入将标准间接提示注入成功率提升三倍，最高攻击合规率可达100%。",
      "failure_mode": "agent工具调用错误处理流程缺乏安全防护，容易被对抗注入绕过常规安全启发式规则。",
