      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "大语言Agent能否在存在层级目标传递、任务依赖的长周期结构化组织中维持连贯行为尚不明确。",
      "method": "提出分层Agent框架TaskWeave，通过四阶段循环维护规划状态，用依赖感知追踪记忆锚定执行。",
      "contribution": "将长周期组织仿真建模为记忆中心协调问题，验证了TaskWeave可支撑长周期连贯组织动态。",
      "limitations": "摘要未提及",
      "key_finding": "结构化仿真记忆是构建可靠大语言模型组织仿真器的核心机制，TaskWeave可维持长周期连贯组织动态。",
      "theme": "多Agent协调仿真",
      "method_family": "multi-agent coordination",
      "agent_setting": "multi-agent",
      "control_mechanism": "通过基于结构化记忆的分层协调框架，维护长周期任务规划状态，锚定多Agent执行行为，提升连贯性。",
      "evaluation_environment": "一年期IT公司组织仿真，指标为组织连贯性、执行锚定、下游企业NLP效用",
      "evaluation_signal": "TaskWeave相比其他多Agent框架，能够维持连贯长周期组织动态，生成锚化工件并适配外部环境。",
