      "theme": "智能体Harness",
      "method_family": "agent harness",
      "agent_setting": "tool-use, multi-agent",
      "control_mechanism": "构建可组合Harness原语，基于执行轨迹反馈迭代演化更新Harness，提供模型训练信号，闭合迭代循环",
      "evaluation_environment": "ALFWorld、GAIA、WebShop、tau^3-Bench、SWE-bench Verified",
      "evaluation_signal": "平均性能提升14.5%，最高达44%，基线性能越低收益越大，性能提升可不依赖模型缩放",
