      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "传统异构群体智能体任务分配采用全局单一信任评分，无法适配能力的技能异质性，浪费专业化价值。",
      "method": "研究技能条件化信任，采用控制相图分析明确适用区间，结合公开基准测试，刻画攻击场景下的性能损失。",
      "contribution": "明确条件化信任生效的特定场景，揭示跨技能信息借用的双刃剑特性，量化攻击下的收益与成本权衡。",
      "limitations": "零证据门限仅能限制无法消除攻击，本文未声称具备Sybil抗性，仅量化了相关权衡。",
      "key_finding": "攻击者可利用跨技能信息借用劫持路由，将路由遗憾从0拉高至0.94，把诚实信任评分+0.19污染为-0.06。",
      "theme": "技能条件化信任",
      "method_family": "multi-agent coordination",
      "agent_setting": "multi-agent",
      "control_mechanism": "提出技能条件化信任替代全局单一评分，引入零证据门限缓解攻击，明确适用场景优化多智能体任务分配。",
      "evaluation_environment": "AppWorld异构智能体公开基准，路由遗憾",
      "evaluation_signal": "攻击可将路由遗憾从0拉高至0.94，将诚实信任评分+0.19污染为-0.06，零证据门限仅能限制无法消除攻击。",
      "failure_mode": "全局信任无法适配能力的技能异质性，跨技能信息借用易被攻击劫持任务路由",
      "reliability_risk": "条件化信任存在跨技能信息污染漏洞，现有防御无法完全消除攻击，威胁任务分配可靠性。",
      "industrial_relevance": "high",
