      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "跟踪WorkBench基准上办公智能体能力与安全的发展趋势，分析当前前沿智能体的表现、错误特征与成本变化",
      "method": "在更新后的WorkBench基准上评测不同阶段的智能体模型，对比多时间节点的结果总结发展规律",
      "contribution": "更新了WorkBench基准，提供改进的数据、代码与新模型评分，揭示了办公智能体能力安全与成本的新特征",
      "limitations": "当前前沿智能体仍会犯下基础错误，偶尔会引发发错邮件这类不可逆转的有害后果",
