      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有大语言模型反穆斯林偏见评估多局限于单轮提示补全，无法适配前沿大模型实际部署的多场景评估需求。",
      "method": "构建包含1200条提示的MIRAGE基准，覆盖三类实际部署场景，在六个前沿模型上开展偏见审计评估。",
      "contribution": "提出MIRAGE偏见审计基准，发布开放评估框架，揭示不同部署条件下大模型反穆斯林偏见的特征。",
      "limitations": "现有基于提示的偏见缓解方法跨场景迁移性差，无法有效缓解智能体决策场景的偏见不对称。",
      "key_finding": "思维链比直接补全放大偏见12%-34%，智能体决策偏见差9-22个百分点，近期冲突背景下偏见升18%-27%。",
      "theme": "大模型偏见评测",
      "method_family": "evaluation/benchmark",
      "agent_setting": "模拟智能体决策，多领域决策任务",
