      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "针对VLM部署时延高成本大、部署后智能体框架静态，现有基准未测试工具工作区视觉证据利用的问题",
      "method": "提出带级联门过滤帧的混合编码降本、基于失败学习的技能库自进化方案，构建新评测基准",
