      "manual_tags": [],
      "problem": "逆材料闭环设计中，昂贵第一性原理计算结果缺乏可靠性校验与可审计性，易影响反馈学习效果。",
      "method": "提出可靠性门控的第一性原理反馈框架，集成多智能体自动DFT、证据分层与可审计反馈流程。",
      "contribution": "提出可迁移的反馈契约，让闭环逆设计学习昂贵计算属性时兼具实用性与可审计性，开放全部数据代码。",
      "limitations": "摘要未提及",
      "key_finding": "经多轮迭代，该框架筛选240万个结构，提交102个候选做DFT验证，最终保留41个化学式的86个合格生成通道。",
      "theme": "多智能体可靠性",
      "method_family": "agent harness",
      "agent_setting": "multi-agent",
      "control_mechanism": "通过可靠性门控对计算结果分层校验，仅纳入合格结果作为反馈更新模型，实现可审计的闭环设计流程。",
      "evaluation_environment": "2DMatPedia衍生候选材料筛选任务",
      "evaluation_signal": "从102个DFT验证候选中保留86个合格生成通道，覆盖41个化学式，全流程数据代码公开可复现。",
      "failure_mode": "不可靠计算结果混入反馈，污染模型训练，降低闭环设计质量",
      "reliability_risk": "依赖昂贵的第一性原理DFT计算，仅面向材料设计领域，方法通用性不足。",
