      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有AI智能体评估方法信号碎片化，难以同时兼顾专家判断质量与评估可扩展性，容易遗漏智能体故障。",
      "method": "提出桥中人(HOB)可扩展评估范式，将人类专家评估知识提前整理，由ProofAgent Harness重复执行规模化对抗评估。",
      "contribution": "提出兼顾专家质量与可扩展性的AI智能体评估新范式，验证该方案可低代价发现现有方法遗漏的智能体故障。",
      "limitations": "摘要未提及",
      "key_finding": "该方法无需大尺寸评估模型，小型Harness大模型即可发现静态基准遗漏的幻影工具调用、策略漂移等多种故障。",
      "theme": "AI智能体评估",
      "method_family": "evaluation/benchmark",
      "agent_setting": "tool-use 金融医疗代码任务",
      "control_mechanism": "基于harness框架，将人类专家评估知识前置预配置，通过重复多轮对抗评估检测智能体的行为问题。",
      "evaluation_environment": "金融、医疗、代码生成三类领域智能体任务",
      "evaluation_signal": "可检测出静态基准遗漏的多种智能体故障，无需大尺寸评估模型即可保证较高的评估质量。",
      "failure_mode": "幻影工具调用、遗漏必需工具调用、策略漂移、不合理拒绝",
      "reliability_risk": "依赖人类专家前置整理领域评估知识，新领域的专家知识适配与整理成本相对较高。",
