      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "长智能体轨迹累积陈旧内容易超出上下文窗口，现有固定间隔压缩不考虑轨迹结构易丢弃有用中间结果",
      "method": "提出SelfCompact框架，含模型可调用的压缩工具与指定压缩时机的轻量规则，无需微调与外部监督",
      "contribution": "实现自适应上下文压缩，效果优于现有方法，大幅降低token成本，弥补了模型的元认知缺口",
      "limitations": "摘要未提及",
