      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有编码智能体安全机制细粒度控制能力不足，现有机制可解释性安全方法不适配多轮动态风险场景。",
      "method": "提出基于机制子空间干预的白盒防御框架AgentLens，从步骤级隐藏表示检测风险，干预单层子空间缓解不安全行为。",
      "contribution": "提出AgentLens安全调控框架，构建带标注多轮轨迹的MAS基准，验证该框架可有效降低智能体有害行为。",
      "limitations": "摘要未提及",
      "key_finding": "干预大语言模型单个网络层中的10维子空间，即可有效减少多轮编码智能体的有害执行行为。",
      "theme": "智能体安全调控",
      "method_family": "model steering",
      "agent_setting": "coding",
      "control_mechanism": "基于机制可解释性定位安全相关的隐藏表示子空间，运行时检测风险并干预子空间，调控不安全行为。",
      "evaluation_environment": "Mechanistic Agent Safety (MAS) 基准，基于三个开源7-9B大语言模型构建",
      "evaluation_signal": "验证AgentLens具备良好安全检测性能，可显著降低编码智能体的有害动作，还支持前瞻风险预判。",
      "failure_mode": "多轮智能体执行中动态安全风险无法被现有方法实现细粒度控制",
      "reliability_risk": "仅在小规模自建基准上验证，尚未验证更大模型与真实复杂编码场景的效果。",
      "industrial_relevance": "high",
