      "title": "Content-Based Smart E-Mail Dispatcher Using Large Language Models",
      "title_zh": "基于内容的大语言模型智能邮件分发器",
      "authors": [
        "K. Paramesha",
        "K R Sriram",
        "Sujan Shetty",
        "Shamanth Kishore",
        "R. Tejaswini"
      ],
      "url": "http://arxiv.org/abs/2606.26593v1",
