      "title": "Agentic Hardware Design as Repository-Level Code Evolution",
      "title_zh": "智能体化硬件设计：仓库级代码演化",
      "authors": [
        "Cunxi Yu",
        "Chenhui Deng",
        "Nathaniel Pinckney",
        "Brucek Khailany"
      ],
      "url": "http://arxiv.org/abs/2606.28279v1",
      "pdf_url": "https://arxiv.org/pdf/2606.28279v1",
