      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "多轮智能体训练中，低决策密度场景下大量常规轮次会引发信号稀释，增大梯度方差降低训练效率。",
      "method": "提出决策密度ρ概念，通过理论分析推导信号稀释对轨迹级信用分配的影响，在可控环境验证结论。",
      "contribution": "揭示多轮智能体信用分配成本由决策密度而非长时域决定，给出信噪比缩放规律，实验验证了理论预测。",
      "limitations": "摘要未提及",
      "key_finding": "批评家误差可控时，轨迹级信噪比随决策密度ρ的-1/2次方缩放，可控实验验证该规律R²达0.999。",
      "theme": "多轮智能体训练",
      "method_family": "policy optimization",
      "agent_setting": "多轮单智能体",
      "control_mechanism": "引入决策密度概念，分析信号稀释对梯度估计的影响，从理论层面优化多轮智能体信用分配的认知。",
      "evaluation_environment": "可精确调节决策密度ρ的可控实验环境",
      "evaluation_signal": "验证了信噪比和决策密度的缩放规律，可控环境中拟合优度R²达0.999，决策密度越低训练步差距越大。",
