      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有软件工程基准多为单轮完整需求设定，无法评估智能体适配真实交互式用户驱动开发的能力。",
      "method": "构建新测试集SWE-Interact，设计基于真实交互统计的用户模拟器，评测编码智能体的交互式任务能力。",
      "contribution": "提出正交评测维度，测试智能体交互式目标发现与用户在环迭代优化能力，量化了现有模型的性能差距。",
      "limitations": "最强模型仍存在过度编码、遗忘需求等问题，弱模型易提前放弃、忽略迭代更新的需求。",
      "key_finding": "最强模型单轮SWE任务解决率约50%，对应SWE-Interact任务仅25%，单轮性能无法迁移到多轮工作流。",
      "theme": "编码智能体评测",
      "method_family": "evaluation/benchmark",
      "agent_setting": "coding",
      "control_mechanism": "通过构建符合真实开发流程的评测基准，评估编码智能体的交互式开发能力，引导模型能力迭代。",
      "evaluation_environment": "SWE-Interact、单轮SWE基准，评测指标为任务解决率",
      "evaluation_signal": "现有模型单轮SWE任务性能无法迁移到多轮用户驱动任务，最强模型解决率从约50%降至25%。",
      "failure_mode": "过度编码、需求遗忘、弱模型提前放弃、忽略指令、重复返工",
      "reliability_risk": "仅提出评测基准，未给出改进现有模型缺陷的方案，覆盖的开发场景仍较为有限。",
      "industrial_relevance": "high",
