      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "LLM智能体的记忆整合会将不确定传言转化为确定错误事实，引发错误服从问题，现有常用修复方法均失效。",
      "method": "构造智能体测试场景，分析智能体置信度的来源，验证不同修复方案的有效性，总结可落地的防护思路。",
      "contribution": "发现了记忆重写产生人造置信度的安全问题，明确置信度来源，指出现有修复缺陷，给出可行方案并开源工具。",
      "limitations": "仅保留原试探性措辞的方法，无法防御攻击者主动编造的高置信谎言。",
      "key_finding": "记忆整合会将模糊保留表述转化为确定断言，Agent服从确定断言远多于模糊表述，现有常用修复方法全部失效。",
      "theme": "Agent事实可靠性",
