      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有多无人机协作的LLM应用缺乏适配的系统评估方案，现有工具无法覆盖真实场景约束需求。",
      "method": "提出面向LLM智能体的轻量多无人机仿真平台MultiUAV-Plat，配套构建基准，提出专用Agent4Drone智能体框架。",
      "contribution": "推出仿真平台、评测基准与专用智能体框架，验证性能优势，为该领域研究提供可复现基础。",
      "limitations": "摘要未提及",
      "key_finding": "Agent4Drone任务通过率达57.9%，较ReAct基线提升27.3个百分点，将总失败任务率从32.4%降至12.9%。",
      "theme": "多无人机智能体评测",
      "method_family": "evaluation/benchmark",
      "agent_setting": "multi-agent/tool-use",
      "control_mechanism": "构建带隐藏验证逻辑的标准化仿真平台，通过专用任务架构规范多无人机智能体的行为流程。",
      "evaluation_environment": "MultiUAV-Plat Benchmark，指标包括任务通过率、验证通过率、失败任务率",
      "evaluation_signal": "Agent4Drone在该基准上任务通过率达57.9%，大幅领先ReAct基线，失败任务率较基线降低19.5个百分点",
      "failure_mode": "LLM智能体在多无人机协同任务中任务通过率低、失败率高",
      "reliability_risk": "仅在自研仿真环境中评测，缺乏真实物理无人机场景的落地验证，实际落地存在不确定性",
      "industrial_relevance": "high",
