      "manual_reason": "",
      "manual_tags": [],
      "problem": "企业AI Agent随技能规模扩大，描述重叠引发技能碰撞路由错误，手动调优存在严重工程瓶颈。",
      "method": "构建自动化技能描述优化流水线，基于误分样本做单次LLM重写优化，辅以诊断方法识别真范围重叠案例。",
      "contribution": "提出自动化技能描述优化方案，验证单次重写即可达到手动调优效果，大幅降本并给出问题诊断方法。",
      "limitations": "仅能解决描述重叠引发的技能碰撞，无法解决技能本身意图范围真实重叠的问题。",
      "key_finding": "仅单次LLM重写就能获得和手动调优相近的F1（79.2%对79.4%），单技能工程耗时从120分钟降至3.8分钟，提升32倍。",
      "theme": "技能描述优化",
      "method_family": "agent harness",
      "agent_setting": "tool-use",
      "control_mechanism": "通过优化Agent的技能自然语言描述，减少技能碰撞，提升路由准确率，大幅降低人工调优的工程成本。",
      "evaluation_environment": "生产企业群聊Agent系统、ToolBench，评测指标为F1、单技能工程耗时",
      "evaluation_signal": "优化后F1与手动调优的差异仅0.2%，落在多种子噪声范围内，工程耗时降低32倍，单次重写捕获绝大多数性能提升。",
      "failure_mode": "技能描述重叠引发的技能路由错误（技能碰撞）",
      "reliability_risk": "无法解决技能本身意图范围真实重叠的问题，这类问题需要额外的架构层面干预。",
