      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有SAR数据增广工作流受异构数据格式、样本验证不足等问题制约，增广决策可靠性与可复现性较差。",
      "method": "提出SAR增广生成智能体SAGA，通过验证器约束规划选择可行增广策略，多维度评估生成数据质量。",
      "contribution": "提出任务导向的SAR数据生成增广智能体框架，提升增广决策可靠性与可复现性，性能优于多个基线。",
      "limitations": "摘要未提及",
      "key_finding": "相比规则、仅LLM、ReAct等基线，SAGA在模式接地、技能规划、无效样本拒绝和下游增广效用上均更优。",
      "theme": "任务驱动智能体框架",
      "method_family": "agent harness",
      "agent_setting": "tool-use/SAR数据生成",
      "control_mechanism": "通过分离语义提议与确定性验证执行，以验证器约束规划、多维度事后质量评估管控智能体行为。",
      "evaluation_environment": "受控智能体基准、下游SAR图像解释任务",
      "evaluation_signal": "评测模式接地、技能规划、无效样本拒绝能力及下游增广效用，对比多种基线的性能差异。",
      "failure_mode": "生成样本缺乏有效验证，增广决策可靠性、可复现性差，无效样本占比高。",
      "reliability_risk": "目前仅适配SAR数据增广场景，跨领域通用能力未验证，落地其他场景需额外适配。",
