      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "训练计算机使用智能体缺乏大规模高质量训练数据，现有最大公开数据集AgentNet做监督微调会引发负迁移，降低模型性能。",
      "method": "构建ProCUA-SFT大规模数据集，通过全自动流水线生成带预可行性检查的合成桌面任务轨迹，蒸馏得到步级微调样本。",
      "contribution": "提出大规模ProCUA-SFT监督微调数据集，大幅提升OSWorld上计算机使用智能体性能，已应用于实际模型训练。",
      "limitations": "摘要未提及",
      "key_finding": "用AgentNet微调UI-TARS 7B会使OSWorld成功率从26.3%降至8-10%，ProCUA-SFT微调可提升至45.0%，比AgentNet版本高35个百分点以上。",
      "theme": "计算机使用智能体",
      "method_family": "evaluation/benchmark",
      "agent_setting": "OS computer-use",
      "control_mechanism": "通过全自动流水线生成大规模高质量合成训练数据，提前做任务可行性检查，蒸馏得到优质微调样本提升智能体性能。",
      "evaluation_environment": "OSWorld，评测指标为任务成功率",
      "evaluation_signal": "ProCUA-SFT微调UI-TARS 7B后，OSWorld任务成功率达45.0%，较base模型提升18.7个百分点，较AgentNet微调版本提升超35个百分点。",
