      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "针对深度研究Agent规划层易被检索池中的对抗文档投毒，导致最终报告整体污染的问题",
      "method": "提出两级攻击FORGE，结合文档内推理伪造与文档间链协调劫持规划，同时提出PRISM指标与轻量防御RQA",
      "contribution": "提出劫持深度研究Agent规划的攻击方法，提出新评测指标与轻量防御，通过实验验证了其有效性",
      "limitations": "摘要未提及",
      "key_finding": "注入5个对抗文档即可达到26.4%PRISM，中毒内容会向事实前提深度迁移，RQA可大幅降低污染",
      "theme": "Agent对抗攻击",
      "method_family": "unlearning/safety",
      "agent_setting": "web/search",
      "control_mechanism": "提出轻量防御根查询锚定，将递归后续提问生成绑定到原始根查询，抵御对抗轨迹劫持攻击",
      "evaluation_environment": "自定义查询集，PRISM指标",
      "evaluation_signal": "注入5个文档的FORGE攻击在25个查询上达到26.4%PRISM，RQA将10查询集PRISM从38.5%降至18.3%",
      "failure_mode": "多轮检索规划的深度研究Agent易被对抗文档投毒，导致输出报告整体污染",
      "reliability_risk": "依赖开放web检索的深度研究Agent易被投毒污染输出，存在输出不可信的安全风险",
