      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "大语言模型智能体多步工具调用任务生产可靠性不足，现有方法无法准确定位动态轨迹的错误根源。",
      "method": "提出AgentTether运行时修复框架，构建依赖感知临界转移图定位错因，结合修复记忆生成指导，支持离线在线部署。",
      "contribution": "无需修改原有智能体与环境，可提升修复效果，减少交互轮次与token消耗，适配现有智能体部署。",
      "limitations": "摘要未提及",
