      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "专家编写维护面向数据科学任务的可复用技能存在人工瓶颈，需验证LLM生成技能是否能作为低代价替代方案。",
      "method": "针对数据科学工作流四个阶段开展LLM生成技能的组件消融实验，在多任务多模型配置下进行大规模对比评测。",
      "contribution": "通过数千次大规模实验验证，单阶段LLM生成技能相比无技能提示无显著性能提升，为实际提示策略提供参考。",
      "limitations": "摘要未提及",
