      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有细胞发育轨迹推断方法需要大量人工干预，要求掌握多种异质性工具，抬高了分析门槛、降低效率。",
      "method": "提出基于大语言模型的自进化多智能体框架SpaCellAgent，包含多智能体规划、动态工具编排、反馈自进化模块。",
      "contribution": "实现了轨迹分析全流程自动化，分析效率提升超40%且性能对齐专家，建立了可扩展的智能体驱动计算生物学范式。",
      "limitations": "摘要未提及",
      "key_finding": "在六个异质性数据集上，该框架在保持专家级分析性能的同时，实现了超过40%的分析效率提升。",
      "theme": "多Agent工具编排",
      "method_family": "multi-agent coordination",
      "agent_setting": "multi-agent tool-use",
