      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有智能体科学机器学习仅靠误差指标选代理模型，无法保证预测结果满足必要的物理约束要求。",
      "method": "提出验证优先的PA-SciML工作流，提前设置物理评估器，生成可机器检查的物理要求，逐个检查候选代理模型。",
      "contribution": "提出带物理审计的智能体发现工作流，可选出满足物理约束的代理模型，在固体力学任务中表现优于基线。",
      "limitations": "摘要未提及",
      "key_finding": "平均误差相近时，仅误差基线选出的模型不满足因果性要求，本方法选出的模型可通过严格物理检查。",
      "theme": "智能体约束校验",
      "method_family": "agent harness",
      "agent_setting": "科学代理模型发现",
      "control_mechanism": "设置前置物理约束验证器，在候选搜索阶段逐个检查代理模型，仅保留通过检查的结果，约束输出合规。",
      "evaluation_environment": "计算固体力学静态弹性、瞬态弹性动力学数值任务",
      "evaluation_signal": "相同平均误差下，仅误差基线无法通过因果性检查，本方法选出的模型可通过严格物理检查，验证误差更低。",
      "failure_mode": "仅依靠误差选模型会得到违背物理约束的无效结果，如违背因果性",
      "reliability_risk": "仅在计算固体力学两个任务验证，方法通用性未在更多领域验证，适用范围尚不明确。",
