      "title": "Self-Evolving Agent Harnesses via Gated Semantic Quality-Diversity",
      "title_zh": "《基于门控语义质量多样性的自进化智能体管控框架》",
      "authors": [
        "Xiaotian Luo",
        "Fengxingyu Wang",
        "Chuanrui Hu",
        "Dizhan Xue",
        "Yafeng Deng"
      ],
      "url": "http://arxiv.org/abs/2607.13683v1",
