      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "基于结果的智能体强化学习仅提供稀疏轨迹级奖励，对中间决策指导不足，存在回合级结果与token级策略学习的监督缺口",
      "method": "提出自进化同策略蒸馏框架SEED，从完成的同策略轨迹提取后见技能，生成稠密token级监督信号联合优化策略",
      "contribution": "提出SEED自进化框架填补监督缺口，实验验证其可稳定提升智能体任务性能与样本效率，泛化性良好",
