      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有智能体评估机制对特定应用工作流效度低，复现评估环境成本高且易漂移，难以细粒度定位问题。",
      "method": "提出写时复制（CoW）评分框架，依托PostgreSQL写时复制机制隔离智能体写入，生成细粒度评估得分。",
      "contribution": "提出低成本的特定应用环境智能体评估框架，可定位工具问题，修复后模型获得可衡量性能提升。",
