      "venue_confidence": "semantic-scholar",
      "venue_source": "semantic-scholar",
      "is_authority_venue": true,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "大语言模型生成规划常违反任务约束，现有方法无法提升模型内在约束感知，影响实际应用可靠性。",
      "method": "提出约束感知强化学习框架CARL，设计约束感知奖励强化大模型的内在约束感知能力。",
      "contribution": "提出无需外部求解器的可扩展端到端框架，实验性能显著优于基线及现有最优推理模型。",
      "limitations": "摘要未提及",
      "key_finding": "CARL通过约束感知奖励强化大模型内在约束关注，规划约束遵守表现显著优于标准RFT及现有最优推理模型。",
      "theme": "约束感知规划",
      "method_family": "agent harness",
      "agent_setting": "任务规划",
      "control_mechanism": "通过对比约束与无约束输入设计约束感知奖励，用强化学习引导大模型生成符合约束的规划，无需额外外部求解器。",
      "evaluation_environment": "BlocksWorld、TravelPlanner、T-Eval规划基准",
      "evaluation_signal": "评测大模型规划的约束遵守能力，结果显示CARL相比基线与现有SOTA，约束关注度显著提升，性能更优。",
      "failure_mode": "大语言模型生成规划违反任务约束",
