      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有技能检索将技能描述视为普通文档，忽略共享描述结构的干扰，导致检索精度不足，无法正确区分目标技能。",
      "method": "提出无训练的SkillSight检索框架，通过语义背景校准和词法证据校准消除共享描述背景的干扰。",
      "contribution": "指出共享描述背景是技能检索偏差的核心来源，所提方法显著提升检索精度与效率，端到端性能优于现有方案。",
      "limitations": "摘要未提及",
      "key_finding": "技能描述中的共享模式会系统性推高稠密检索相关性得分，SkillSight最高可将Recall@10提升20.21个百分点，速度快1248倍。",
      "theme": "技能检索",
      "method_family": "agent harness",
      "agent_setting": "tool-use",
      "control_mechanism": "通过校准技能检索中共享描述背景的干扰，提升技能检索的准确性与效率，优化智能体的能力选择行为。",
      "evaluation_environment": "SRA-Bench、SkillBench-Supp，评测指标含Recall@10、端到端整体性能",
      "evaluation_signal": "Recall@10最高提升20.21个百分点，端到端性能最高超出LLM Selection 4.97个百分点，速度最高快1248倍。",
      "failure_mode": "共享描述背景导致技能检索存在偏差，无法有效区分目标能力，掩盖任务相关信号",
      "reliability_risk": "仅在封闭技能基准上验证，未在大规模开放真实场景验证方法的实际泛化能力。",
