      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "针对有状态自主智能体中出现的Chronos记忆类持续性攻击漏洞，传统端点内容过滤无法防御该新型威胁。",
      "method": "在World of Workflows基准下形式化攻击威胁模型，梳理分类针对该漏洞的分层深度防御体系。",
      "contribution": "形式化了基于记忆的持续性攻击威胁模型，梳理了分层防御体系，分类总结了该领域的新兴防御框架。",
      "limitations": "摘要未提及",
