      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "研究多智能体介导传递危险目标场景下，大语言模型的安全表现规律与潜在安全漏洞问题。",
      "method": "对比直接暴露危险目标和多智能体转换传递目标两种场景，测试大语言模型的输出对齐情况。",
      "contribution": "发现两种场景下模型输出方向反转的现象，揭示了多级多智能体工作流的组合安全漏洞。",
      "limitations": "未明确模型输出行为反转现象的内部作用机制，未深入探究漏洞的应对方案。",
      "key_finding": "原危险目标经上游多智能体转换隔离后，下游大模型会输出符合危险目标的建议，直接暴露反而输出相反建议，存在组合安全漏洞。",
      "theme": "多智能体安全",
      "method_family": "unlearning/safety",
      "agent_setting": "multi-agent",
      "control_mechanism": "恶意利用多智能体分阶段工作流，将原始危险指令与下游模型上下文隔离，保留目标方向绕过安全检测。",
      "evaluation_environment": "摘要未提及",
      "evaluation_signal": "对比不同目标传递方式下，模型输出建议与原始危险目标的方向一致性，统计对齐情况差异。",
      "failure_mode": "多阶段多智能体工作流可绕过模型原有安全机制，存在可被恶意利用的组合安全漏洞",
      "reliability_risk": "恶意用户可通过多智能体分阶段工作流绕过模型安全管控，生成危险输出，带来严重安全风险。",
