      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "AI编码智能体的公开技能文件缺乏安全筛查，存在恶意技能带来的供应链攻击风险，尚无系统性防御方案。",
      "method": "提出SkillGate安全网关，采用正则预过滤加LLM判断的混合流水线，仅对疑似片段调用LLM以降低检测成本。",
      "contribution": "提出针对编码智能体恶意技能的检测方案，检测效果优异，大幅降本，性能显著优于现有同类工具。",
      "limitations": "摘要未提及",
      "key_finding": "SkillGate在SkillsBench上F1达0.817，相比全文件检测减少77%LLM输入tokens，AUPRC比现有工具高5-6倍。",
      "theme": "恶意技能检测",
      "method_family": "unlearning/safety",
      "agent_setting": "coding",
      "control_mechanism": "在编码智能体安装技能前开展安全筛查，通过正则预过滤跳过安全文件，仅对疑似片段调用LLM判断以降低成本。",
      "evaluation_environment": "SkillsBench，评测检测效果、筛查成本、运行开销与误报表现",
      "evaluation_signal": "在含1650个样本（9.1%为恶意）的SkillsBench上，SkillGate F1=0.817，FPR=1.13%，AUPRC远超现有工具，降本77%。",
      "failure_mode": "恶意技能文件可篡改编码智能体行为，带来信息窃取、代码注入等供应链安全风险，现有无系统性防御。",
