      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有记忆增强LLM智能体采用静态逐字重放经验的范式，忽略经验与当前决策情境的差距，易引发负迁移。",
      "method": "提出MemHarness框架，每步决策用统一策略模型基于当前状态重构检索经验，通过GRPO端到端训练获得能力。",
      "contribution": "提出情境化重构记忆的智能体框架，验证其性能优于基线，提升了分布外鲁棒性与智能体推理能力。",
      "limitations": "摘要未提及",
      "key_finding": "记忆重构目标不仅能避免负迁移，还可作为训练潜在引导，从根本上提升大模型智能体的内在推理能力。",
      "theme": "智能体记忆增强",
      "method_family": "agent harness",
      "agent_setting": "交互式决策任务",
      "control_mechanism": "通过MemHarness框架在每个决策步骤基于当前状态重构过往记忆，以GRPO训练优化，适配当前情境减少负迁移。",
      "evaluation_environment": "ALFWorld、WebShop，评测任务性能与分布外鲁棒性",
      "evaluation_signal": "MemHarness性能大幅优于对比基线，在分布外场景鲁棒性更强，同时可提升智能体的内在推理能力。",
