      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "目前缺少有效评估框架，无法检验执行商业任务的LLM智能体是否满足著作权法合规要求。",
      "method": "构建包含三类真实商业任务的Copyright-Bench基准，通过提示变体模拟用户偏好和时间压力，评估智能体合规性。",
      "contribution": "提出面向LLM智能体著作权合规评估的基准Copyright-Bench，揭示了当前主流智能体的侵权行为规律。",
      "limitations": "摘要未提及",
      "key_finding": "现有LLM智能体在存在合法公共领域替代内容时仍会选侵权内容，开源模型侵权率随用户偏好和时间压力升高。",
      "theme": "智能体合规评测",
      "method_family": "evaluation/benchmark",
      "agent_setting": "tool-use",
      "control_mechanism": "本文构建专门的合规评估基准，识别智能体的侵权行为，为后续智能体合规控制提供评估基础。",
      "evaluation_environment": "Copyright-Bench基准，涵盖网站开发、商品设计、演示文稿制作三类商业任务",
      "evaluation_signal": "评测LLM智能体在商业任务中的著作权侵权选择率，验证用户偏好与时间压力对开源模型侵权率的影响。",
      "failure_mode": "LLM智能体在存在合法替代内容时仍主动选择受著作权保护的侵权内容",
      "reliability_risk": "LLM智能体的无意识著作权侵权会给下游商业应用带来较高的法律合规风险。",
      "industrial_relevance": "high",
      "read_priority": "high",
