      "title": "Agentic Method for Deterministic Validation of Legacy Code Migration",
      "title_zh": "用于遗留代码迁移确定性验证的智能体方法",
      "authors": [
        "Andras Ferenczi",
        "Jordan Docherty",
        "M.D. Bessonov",
        "Matthew Findlay",
        "Krishna Lingamneni"
      ],
      "url": "http://arxiv.org/abs/2607.28271",
      "pdf_url": "http://arxiv.org/pdf/2607.28271",
      "category": "via-citation",
