      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "合规关键业务流程中，大语言模型智能体自主决策存在识别风险后未触发政策要求的强制人工审批的安全隐患",
      "method": "提出受治理APA运行时决策架构，通过输入校验、封闭动作空间、政策派生安全护栏和确定性回退约束大模型自主性，证明其满足下限安全属性",
      "contribution": "提出带安全保证的合规决策架构，实验验证其可提升合规决策召回率与稳定性，解决敏感风险漏 escalate 问题",
      "limitations": "仅为单流程双模型的概念验证，安全保证不覆盖输入污染、政策错误、提示注入等多类问题",
      "key_finding": "无治理Qwen2.5对43个敏感风险案例的人工审批召回为0，加本文护栏后召回升至1.0，稳定性从0.73升至1.0且无假阳性",
      "theme": "智能体安全管控",
      "method_family": "agent harness",
      "agent_setting": "tool-use",
      "control_mechanism": "通过架构层面的治理，加入政策派生的下限安全护栏，约束大模型自主决策空间，保证决策满足合规政策最低要求",
      "evaluation_environment": "结构化员工入职案例数据集，评测指标为人工审批召回率、合规决策稳定性",
      "evaluation_signal": "本文方法可将敏感风险案例的人工审批召回提升至1.0，大幅提升决策稳定性，未额外引入Qwen2.5的假阳性升级",
      "failure_mode": "大模型自主决策时识别风险后未按政策要求触发人工审批，合规决策稳定性差",
      "reliability_risk": "仅单场景概念验证，泛化性未验证，安全保证不覆盖输入污染、提示注入等常见落地风险",
      "industrial_relevance": "high",
