      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "动态多智能体环境中对手策略持续更新，现有静态环境技能更新方法基于过时参考，适配效果差。",
      "method": "提出对手感知选择性进化方法OASE，基于对手历史策略快照对比筛选技能修改，仅增益达标才予以采纳。",
      "contribution": "提出适配动态多智能体环境的技能更新框架，实验验证其性能优于基线，可大幅减少无效技能更新。",
      "limitations": "摘要未提及",
      "key_finding": "OASE相比Reflexion风格基线，在两个测试场景中最终平衡距离更低，且采纳的技能修改量大幅减少。",
      "theme": "多智能体技能进化",
      "method_family": "policy optimization",
      "agent_setting": "multi-agent",
      "control_mechanism": "通过基于历史对手策略快照的公平对比，设置收益阈值筛选技能修改，替换盲目更新实现稳定策略适配。",
      "evaluation_environment": "一级密封价格拍卖、私人成本古诺竞争，指标为最终平衡距离、技能修改接受量",
      "evaluation_signal": "在两个测试场景中，OASE相比Reflexion基线最终平衡距离更低，且大幅减少无足够收益支撑的技能修改。",
      "failure_mode": "静态环境技能更新方法在动态多智能体中会产生大量无收益支撑的无效策略变更",
      "reliability_risk": "仅在两类简单博弈场景验证，未测试复杂开放环境，方法泛化性有待进一步验证。",
