      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "机器人学习领域技术路线分化，“技能”概念存在歧义，缺乏清晰统一的分类梳理框架。",
      "method": "围绕权重与技能的分化轴构建分类框架，按自我改进程度梳理不同技术路线的代表性系统。",
