      "theme": "大模型安全治理",
      "method_family": "unlearning/safety",
      "agent_setting": "非Agent论文",
      "control_mechanism": "通过构建分层分阶段的安全导向生命周期框架，明确各阶段安全需求，对齐现有监管规则，强化LLM系统安全管控。",
      "evaluation_environment": "摘要未提及",
