      "title": "GenOS: Compositional Certificates for Semantic Robustness in AI Code Generation",
      "title_zh": "GenOS：AI代码生成中语义鲁棒性的组合证书",
      "authors": [
        "Corrado Priami"
      ],
      "url": "http://arxiv.org/abs/2608.03588v1",
