      "id": "2608.03585",
      "direction_id": "agent-skills-harness",
      "direction_name": "Agent Skills 与 Harness",
      "week": "2026-W32",
      "title": "From Social Coding to Agentic Coding: Productivity and Relational Reconfiguration in Open-Source Communities",
      "title_zh": "从社会编码到智能体编码：开源社区的生产力与关系重构",
      "authors": [
        "Mengying Zhou",
        "Yongjie Yin",
        "Yang Chen"
      ],
      "url": "http://arxiv.org/abs/2608.03585v1",
      "pdf_url": "https://arxiv.org/pdf/2608.03585v1",
