      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有大模型智能体技能演化多为局部更新，忽略技能间关联，更新易过拟合，跨任务泛化能力差。",
      "method": "提出全局化技能演化框架GSE，构建技能关系图建模关联，结合聚类合并与重放验证优化泛化性。",
      "contribution": "提出GSE框架，性能远超现有方法，工业内部部署F1得分提升61.4%，验证了方法有效性。",
      "limitations": "摘要未提及",
      "key_finding": "GSE对比现有演化方法，精度提升6.1%~96.4%，召回提升13.1%~180.0%，工业部署F1提升61.4%。",
      "theme": "智能体技能演化",
