      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有先SFT后RL的视觉工具使用训练方案存在两阶段监督不对齐，导致模型难以学到有效的工具调用能力。",
      "method": "提出ToolVision框架，SFT阶段筛选保留学生可复现的有效轨迹，RL阶段仅对工具确有增益的成功调用奖励。",
