      "title": "RLMOpt: Adaptive Prompt Optimization via Recursive Language Models",
      "title_zh": "RLMOpt：基于递归语言模型的自适应提示优化",
      "authors": [
        "Subhash Bangalore Satheesha",
        "Nirvik Pande",
        "Deepthi Duddempudi",
        "Bharath Dandala"
      ],
      "url": "http://arxiv.org/abs/2608.10471v1",
      "pdf_url": "https://arxiv.org/pdf/2608.10471v1",
