      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "长范围工具使用智能体的强化学习训练中，多轮采样产生长上下文，原有设计适配性差且显存开销过高。",
      "method": "提出模块化训练系统SINKFLEX-RL，设计sink感知的FlexAttention路径，无需单独价值模型完成训练优化。",
      "contribution": "提出适配长范围工具任务的模块化RL训练系统，有效降低峰值显存，提升了长任务的验证奖励。",
      "limitations": "摘要未提及",
      "key_finding": "优化后注意力在4096 tokens下将峰值VRAM降低19.7%，8192 tokens可运行而eager基线显存耗尽，验证奖励从0.25升至0.44。",
      "theme": "工具使用智能体",
      "method_family": "tool-use control",
      "agent_setting": "tool-use",
      "control_mechanism": "通过设计模块化强化学习训练系统与优化注意力路径，降低训练显存开销，提升长范围工具任务训练可行性。",
      "evaluation_environment": "Tau2Bench零售任务、固定配置内存基准，评测指标为验证奖励、峰值VRAM",
      "evaluation_signal": "该方案可显著降低训练峰值显存占用，支持8192 token长上下文训练，同时提升长范围工具任务的验证奖励。",
      "failure_mode": "长范围工具任务训练中长上下文导致显存占用过高，大长度序列训练容易显存耗尽",
