      "title": "Self-evolving network verifiers",
      "title_zh": "自演进网络验证器",
      "authors": [
        "Ioannis Protogeros",
        "Tibor Schneider",
        "Laurent Vanbever"
      ],
      "url": "http://arxiv.org/abs/2608.11340v1",
