      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有智能体技能进化依赖单轮问答反馈，多轮缺陷不可见致进化停滞，标量治理无法定位修复问题。",
      "method": "提出SkillEvo框架，将多轮用户模拟转化为反馈生成器，新增独立治理层主动修复技能退化与结构膨胀。",
      "contribution": "提出可实现持续技能进化的SkillEvo框架，在生产云服务技能评测中性能大幅优于已有进化方法。",
      "limitations": "摘要未提及",
      "key_finding": "多轮交互反馈可持续提供可信进化梯度，SkillEvo性能分别超出两个基线23.0和15.4个百分点。",
      "theme": "Agent技能进化",
      "method_family": "skill generation",
