      "title": "Static analysis-guided agentic AI translation enables Rust as a full stack bioinformatics language",
      "title_zh": "静态分析引导的智能体AI翻译让Rust成为全栈生物信息学语言",
      "authors": [
        "Johan Henriksson"
      ],
      "url": "http://arxiv.org/abs/2608.13029v1",
