      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "扩展自动研究智能体的强化学习时，环境执行独占计算资源与时间，成为训练成本瓶颈，阻碍智能体规模扩大。",
      "method": "提出世界模型强化学习WMRL，用世界模型替代真实环境执行，搭配在线去偏与逆方差降噪抵消偏差噪声。",
      "contribution": "提出解决训练瓶颈的WMRL框架，理论证明收敛性提升，实验实现3-4倍训练加速，性能超越标准RL基线。",
      "limitations": "摘要未提及",
      "key_finding": "WMRL可将自动研究智能体训练加速3-4倍，4B/9B参数模型性能超过48B/120B参数的大模型。",
      "theme": "智能体规模扩展",
      "method_family": "policy optimization",
      "agent_setting": "auto-research",
      "control_mechanism": "通过世界模型替代真实环境执行，结合去偏降噪降低训练成本，实现更大规模智能体的后训练优化。",
      "evaluation_environment": "AutoResearch任务基准、留出测试基准、具身VLA策略任务基准",
      "evaluation_signal": "训练速度提升3-4倍，小参数模型性能超过大参数基线模型，方法可迁移至具身策略任务。",
      "failure_mode": "强化训练扩展时环境执行成为资源瓶颈，推高训练成本阻碍智能体规模扩大。",
