      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "生产环境中的数据漂移会导致模型性能衰退，现有方案更新效率低、可靠性不足。",
      "method": "提出双过程认知架构KC-Agent，结合快慢系统，通过结构化记忆复用方案，加入原子变更与回滚机制。",
      "contribution": "在多个数据集取得SOTA性能，实现91%的效率加速，验证了认知类自动化模型改进方案的实用性。",
      "limitations": "摘要未提及",
      "key_finding": "KC-Agent的知识整合机制相比慢变体实现91%加速同时保持更高精度，性能显著优于四类主流基线认知架构。",
      "theme": "Agent认知架构",
      "method_family": "agent harness",
      "agent_setting": "自动ML模型改进",
      "control_mechanism": "通过双过程分工、结构化知识复用、原子变更规则与回滚机制，保障模型更新的可靠性与效率。",
      "evaluation_environment": "真实NASA涡轮风扇数据、可控漂移合成数据集，指标含准确率、执行时间、LLM智能评分",
      "evaluation_signal": "达到76.8%准确率、13.2秒执行时间，知识整合带来91%加速，性能显著优于四个基线认知架构。",
      "failure_mode": "摘要未提及",
      "reliability_risk": "仅在中小规模数据集验证，未开展大规模工业场景测试，落地泛化性有待验证。",
      "industrial_relevance": "high",
