      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有LLM智能体不确定性量化依赖局部信号，忽略长程依赖，难以提前识别起源于多步前的智能体故障。",
      "method": "提出轨迹级UQ框架RUPA，将执行历史建模为带依赖边的有向轨迹图，通过图上不确定性传播得到全轨迹置信度估计。",
      "contribution": "提出的RUPA性能优于现有UQ方法，可实现更准确的不确定性估计与更早故障检测，为可信智能体执行打下基础。",
      "limitations": "摘要未提及",
