      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "知识工作智能体处理多格式数字产物时，不同操作环节的工作空间状态版本不一致，缺乏显式统一约定。",
      "method": "提出StagedWorkspace版本化工作空间，将解析记录、修改差异与原生文件的内容哈希绑定，支持双视图访问。",
      "contribution": "明确工作空间状态是知识工作智能体的实验变量，所提方案在多个公开基准上实现了大幅的性能提升。",
      "limitations": "摘要未提及",
      "key_finding": "双视图相对单视图，OfficeQA Pass@1提升8.3-12.1个百分点，APEX平均分提升4.7-9.2分，diff可见可提升得分。",
      "theme": "智能体工作空间",
      "method_family": "agent harness",
      "agent_setting": "知识工作文件编辑",
      "control_mechanism": "通过设计版本化工作空间框架，显式绑定各操作环节的状态版本，规范智能体知识编辑行为，提升任务表现。",
      "evaluation_environment": "OfficeQA Pro、APEX-Agents，评测指标为Pass@1、平均rubric得分",
      "evaluation_signal": "所提双视图方案在所有测试模型上表现均优于单视图，在两个基准上相对同模型已有结果提升显著。",
      "failure_mode": "不同操作环节工作空间状态版本不一致，同一产物的状态不匹配",
      "reliability_risk": "对多格式大规模项目的适配成本未明确，跨场景兼容性未验证，存在落地适配风险。",
