      "title": "Teach and Grow: An Agent-Centered Architecture for General Robot Learning",
      "title_zh": "教与生长：面向通用机器人学习的以智能体为中心的架构",
      "authors": [
        "Chang Nie",
        "Zhe Liu",
        "Hesheng Wang"
      ],
      "url": "http://arxiv.org/abs/2608.17209v1",
      "pdf_url": "https://arxiv.org/pdf/2608.17209v1",
