      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "长周期智能体的技能选择决策缺乏适配训练信号，现有方法存在选择器信用饥饿问题，性能随轨迹延长恶化。",
      "method": "提出SkillGate方法，划分两个独立信用通道，结果信用分配给执行token，局部优势分配给技能命名token。",
      "contribution": "识别了技能选择训练中的选择器信用饥饿问题，提出的SkillGate显著提升了长周期智能体的任务成功率。",
      "limitations": "摘要未提及",
      "key_finding": "现有方法存在选择器信用饥饿，正确技能选择也会因后续执行失败受罚，问题随轨迹变长加剧，SkillGate将9B策略成功率从40.8%提至53.2%。",
      "theme": "智能体技能选择",
      "method_family": "policy optimization",
      "agent_setting": "tool-use",
      "control_mechanism": "通过拆分信用分配通道，分别给执行token和技能选择token分配对应的信用信号，改进技能选择的训练效果。",
      "evaluation_environment": "五个智能体基准任务，核心评测指标为智能体试验成功率",
      "evaluation_signal": "16候选技能设置下，将9B参数策略的试验成功率从40.8%提升至53.2%，减少三分之二的错误候选暴露。",
      "failure_mode": "选择器信用饥饿，正确技能选择会因后续执行失败被错误惩罚，性能随轨迹变长恶化",
      "reliability_risk": "仅在有限规模候选集和标准基准验证，未验证更长周期真实场景的泛化效果。",
