      "title": "EviDx: Evidence-Aware Active Diagnosis with Scaffolded LLM Agents",
      "title_zh": "EviDx：基于支架式大语言模型智能体的证据感知主动诊断",
      "authors": [
        "Lihang Zeng",
        "Shaoting Zhang",
        "Xiaofan Zhang"
      ],
      "url": "http://arxiv.org/abs/2608.24570v1",
      "pdf_url": "https://arxiv.org/pdf/2608.24570v1",
