      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有基于同源策略的浏览器安全模型，无法满足多主体Web环境下LLM智能体工具调用的信任保障需求，存在三类安全风险。",
      "method": "提出双层智能体运行时架构WebMCP-Phalanx，结合加密信任锚绑定与双智能体分层隔离检查机制管控信任边界。",
      "contribution": "提出面向浏览器集成LLM智能体的信任防护架构，在不损失任务效用的前提下大幅降低各类攻击的成功率。",
      "limitations": "白盒自适应攻击者可在检查前调用恶意工具，绕过现有基于描述的过滤防护机制。",
      "key_finding": "原生归属机制将撤销覆盖攻击成功率从100%降至0，双智能体拦截全部80次提示注入，仅80次工具返回攻击中2次成功。",
      "theme": "智能体信任防护",
      "method_family": "tool-use control",
      "agent_setting": "web/tool-use",
      "control_mechanism": "通过双层运行时架构，用加密信任锚绑定工具来源，隔离语义检查与特权工具执行，保障工具调用安全。",
      "evaluation_environment": "人工构造的LLM智能体工具调用攻击测试，评测指标为攻击成功率、任务效用",
      "evaluation_signal": "防护后攻击成功率大幅下降，任务效用与无攻击基线无统计差异，仅白盒自适应攻击可绕过防护。",
      "failure_mode": "智能体工具调用存在归属欺骗、生命周期失控、语义提示注入三类安全失效问题。",
      "reliability_risk": "现有防护机制仍可被白盒自适应攻击者绕过，存在未完全解决的安全风险。",
