      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有智能体语言模型训练依赖轨迹数据，获取广覆盖的此类数据成本高，公开技能未被充分用于训练。",
      "method": "提出技能预训练方法SPT，基于公开多文件技能包构建SkillCorpus，辅以参考插入策略保留文件关联，用因果语言建模训练。",
      "contribution": "证明公开技能包是训练智能体语言模型的宝贵数据源，SPT稳定提升智能体性能，同时基本保留模型通用性能。",
      "limitations": "摘要未提及",
      "key_finding": "在多个模型规模和后训练配方下，SPT相比基线稳定提升智能体性能，混合通用退火语料还能获得额外收益。",
      "theme": "智能体技能预训练",
      "method_family": "agent harness",
