      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有语音智能体训练依赖文本或闭源接口，无法端到端优化原生语音智能体，强化学习训练成本过高。",
      "method": "构建无需外部ASR/TTS的原生音频智能体训练环境SpeechGym，采用逐轮过程奖励训练语音智能体。",
      "contribution": "提出可端到端训练的原生语音智能体训练环境，训练后任务成功率翻倍，开源模型排名大幅提升。",
      "limitations": "摘要未提及",
      "key_finding": "语音智能体的失败多为感知错误而非推理缺陷，逐轮过程奖励可解决奖励稀疏，任务成功率提升超一倍。",
      "theme": "语音智能体训练",
      "method_family": "agent harness",
      "agent_setting": "multi-agent tool-use",
      "control_mechanism": "构建端到端可训练的本地原生音频环境，通过逐轮过程奖励提供训练信号优化智能体行为。",
      "evaluation_environment": "独立实现的语音基准，评测指标为任务成功率、使用轮次与token量",
      "evaluation_signal": "训练后任务成功率提升一倍多，将开源模型从基准榜垫底提升至第二名，且消耗更少轮次与token。",
      "failure_mode": "语音感知错误引发工具参数错误，错误级联导致任务失败，还可能出现未授权操作",
      "reliability_risk": "基于现有文本基准修改，原生语音复杂场景的泛化能力未验证，摘要未提及落地测试。",
