      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "大语言模型工具使用中，渐进式工具披露与提示缓存有效性存在冲突，工具列表变更会导致缓存前缀失效。",
      "method": "提出双路径路由架构CacheRouter，将工具选择与交付分配至独立通道，主模型保留固定前缀，路由子模型负责长尾工具选择。",
      "contribution": "解决了渐进披露与缓存的冲突，支持工具动态更新，提升缓存命中率，大幅降低工具调用的输入成本。",
      "limitations": "摘要未提及",
      "key_finding": "该方案在测试中token级缓存命中率最高达95.2%，输入成本可降至无缓存基线的8%，降本效果显著。",
      "theme": "工具路由优化",
      "method_family": "tool-use control",
      "agent_setting": "tool-use",
      "control_mechanism": "通过双路径路由架构隔离主模型与新增长尾工具，保持主模型请求前缀固定，兼顾缓存效率与动态工具扩展。",
      "evaluation_environment": "55个功能查询、30轮对话测试，评测指标为缓存命中率、输入成本",
      "evaluation_signal": "测试中token级缓存命中率分别达90.99%和95.2%，输入成本降至无缓存基线的12%和8%，降本效果明显。",
      "failure_mode": "工具列表变更导致提示缓存失效，推高工具调用的推理成本",
