      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "研究针对工具使用型LLM智能体，验证失败信用路由能否优化零阶扰动预算分配，提升池内样本效率",
      "method": "在合成环境、多款开源小模型、三类任务上测试六种分配方案，做统计检验对比均匀分配基线",
      "contribution": "验证失败信用路由并未提升池内样本效率，记录了冻结LLM上ZO/ES实验的三类静默失效模式",
      "limitations": "仅在未见过的BFCL函数上发现软分配小幅提升，该提升的作用机制未得到验证",
      "key_finding": "池内任务对比中，所有方案相较均匀分配无统计显著提升，信用错配最多会带来0.118AUC的性能下降",
      "theme": "智能体信用分配",
      "method_family": "policy optimization",
