      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "外部化的软件仓库特定智能体技能会随版本更新静默过期，现有前沿智能体难以可靠维护这类过时技能。",
      "method": "提出Repo2Skill-Evo框架，将仓库版本过渡转化为技能维护任务，要求智能体基于版本补丁更新过期技能、保留有效内容。",
      "contribution": "针对仓库技能静默过期问题开展实证研究，测试了前沿智能体的技能维护能力，揭示了现有方法的不足。",
      "limitations": "当前测试的所有前沿大语言模型智能体都无法可靠维护过期仓库技能，该问题尚未得到有效解决。",
      "key_finding": "所有测试的版本过渡都存在技能过期，六个前沿智能体avg@3宏观F1仅29.9%-69.7%，无法可靠维护技能。",
      "theme": "仓库技能维护",
      "method_family": "evaluation/benchmark",
      "agent_setting": "coding",
      "control_mechanism": "将仓库版本过渡转化为结构化技能维护任务，依托版本补丁引导智能体更新过期技能、保留有效内容。",
      "evaluation_environment": "57个真实世界软件仓库，评测指标为补丁对齐移除指标下的avg@3宏观F1",
      "evaluation_signal": "所有测试版本过渡均存在技能失效，六个前沿智能体avg@3宏观F1仅29.9%-69.7%，存在遗漏过期和过度编辑两类错误。",
      "failure_mode": "外部化仓库技能会随版本更新静默过期，智能体易遗漏过期内容或过度编辑，无法可靠维护技能。",
      "reliability_risk": "面向软件仓库的智能体技能会静默过期，现有模型无法可靠维护，长期运行的可靠性难以保障。",
