      "manual_tags": [],
      "problem": "长程交互环境下LLM工具调用智能体可靠性不足，现有方法难以系统生成用于训练的丰富验证理由。",
      "method": "提出CAST批评感知训练框架，将稀疏任务结果转化为动作级监督，合成动作有效性理由优化策略模型。",
      "contribution": "提出CAST批评感知训练框架，在动态工具调用基准上性能优于大基线，有效提升长程环境LLM智能体可靠性。",
      "limitations": "摘要未提及",
      "key_finding": "基于CAST微调Qwen3模型，零售任务pass^4较GPT-OSS-120B提升超10%，域外远程医疗任务额外提升9%。",
      "theme": "工具调用可靠性",
      "method_family": "tool-use control",
