      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有多模态大语言模型多智能体边缘部署策略忽略工作流依赖与配置时延，难以适配边缘资源异构特性。",
      "method": "将智能体协作建模为有向无环图，分别提出基于动态规划的单请求优化与基于B级启发的多请求在线调度算法。",
      "contribution": "所提算法在资源约束下提升请求完成率，实验验证最高降低平均时延42.62%，显著提升高负载环境吞吐量。",
      "limitations": "摘要未提及",
      "key_finding": "在异构多模态LLM多智能体边缘部署中，考虑依赖与配置成本的算法最高可降平均时延42.62%，显著提升高负载吞吐量。",
      "theme": "智能体边缘部署",
