      "hf_upvotes": 0,
      "citation_count": 0,
      "venue": "",
      "venue_year": "",
      "venue_type": "",
      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有生物信息学大语言模型智能体将规划等交互视为瞬时过程，难以支撑长周期任务结论关联支撑证据。",
      "method": "提出多智能体harness Bioinfoysis，以持久化工件锚定分析，结合全局规划与证据驱动重规划，实现运行时验证。",
      "contribution": "在多个公开基准取得SOTA精度，证明可靠生物信息学自动化依赖管控流程的harness而非仅模型能力。",
      "limitations": "摘要未提及",
      "key_finding": "在BixBench取得82.4%的SOTA准确率，四个底层大模型上，SeqQA2准确率从27.81%提升到64.13%，DbQA2从3.13%提升到31.25%。",
      "theme": "多智能体框架",
      "method_family": "agent harness",
      "agent_setting": "multi-agent/tool-use/bioinformatics QA",
      "control_mechanism": "通过Bioinfoysis harness框架，采用持久化工件锚定、规划检查清单、结构化交接、运行时验证管控智能体执行。",
      "evaluation_environment": "BixBench、LAB-Bench 2，评测指标为回答准确率",
      "evaluation_signal": "对比四个原生底层大语言模型，评测Bioinfoysis在生物信息学问答任务上的准确率提升，在BixBench达到SOTA。",
