      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有视觉智能体学习使用放大工具依赖大规模监督微调预热，需要额外标注，学习效率偏低",
      "method": "提出无需SFT预热的多模态大模型工具学习内在奖励，采用InfoNCE风格，以渐难负工具调用对比课程为训练信号",
      "contribution": "提出无需SFT预热的放大工具学习方法，构建可扩展合成评测数据集，在多个基准上性能优于现有基线",
      "limitations": "摘要未提及",
