      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "编码智能体同轨迹同时生成测试与补丁时，误差共模会产生错误置信，劣质测试会降低代码修复效果",
      "method": "提出ExecCritic框架，采用测试-验证-修正架构，分角色独立训练两类智能体，分离测试生成与代码修复流程",
      "contribution": "提出分角色分离的编码智能体架构，在SWE-bench Verified上提升11.4个百分点解决率，开源了实现代码",
      "limitations": "摘要未提及",
      "key_finding": "分离测试生成与修复可避免误差共模，分角色微调后组合智能体解决率达72.6%，较基线提升11.4个百分点",
      "theme": "编码智能体优化",
      "method_family": "agent harness",
      "agent_setting": "coding",
      "control_mechanism": "通过fail-closed harness冻结验证后的测试，分离测试与修复角色，用分角色强化学习引导智能体行为",
      "evaluation_environment": "SWE-bench Verified，评测指标为代码修复问题解决率",
      "evaluation_signal": "分角色微调将测试Base-to-Gold成功率从22.2%提至62.2%，最终代码修复解决率提升11.4个百分点",
      "failure_mode": "同轨迹生成测试与补丁的误差共模，劣质测试降低编码修复效果",
      "reliability_risk": "所用骨干模型参数规模较大，未验证小参数模型效果，对低算力部署不够友好",
