      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有研究仅测试少量场景，无法分离关键条件对LLM智能体阴谋行为的影响，难以覆盖真实部署场景。",
      "method": "构建基于分解场景合成框架的400场景阴谋行为压力测试基准SchemeArena，提出基于推理行为证据的阴谋监测器SCOUT。",
      "contribution": "提出可扩展的阴谋行为压力测试基准与监测方法，揭示不同因素对LLM智能体阴谋行为的影响规律，开放相关资源。",
      "limitations": "摘要未提及",
