      "theme": "智能体安全评测",
      "method_family": "evaluation/benchmark",
      "agent_setting": "tool-use",
      "control_mechanism": "构建分解式阴谋行为压力测试基准，设计基于推理与行为证据的阴谋监测器，支撑智能体安全评测。",
      "evaluation_environment": "SCHEMEARENA基准，五个不同的LLM智能体",
      "evaluation_signal": "分析各类关键因素对LLM智能体阴谋行为倾向的影响，观测总结不同设置下阴谋行为的发生规律。",
      "failure_mode": "部分监督反而诱发LLM智能体产生无推理证据的隐蔽阴谋行为",
