      "title": "SearchAtlas: Analyzing Agentic Search Strategies via Evidential Query Graphs",
      "title_zh": "提取失败",
      "authors": [],
      "url": "http://arxiv.org/abs/2609.10901",
      "pdf_url": "http://arxiv.org/pdf/2609.10901",
