      "id": "2609.12582",
      "direction_id": "agent-skills-harness",
      "direction_name": "Agent Skills 与 Harness",
      "week": "2026-W38",
      "title": "NovaFabric: Tamper-Evident, Replayable Evidence for Autonomous AI Agent Runs",
      "title_zh": "提取失败",
      "authors": [
        "Mohsen Seyedkazemi Ardebili"
      ],
      "url": "http://arxiv.org/abs/2609.12582",
