      "id": "2609.18849",
      "direction_id": "agent-skills-harness",
      "direction_name": "Agent Skills 与 Harness",
      "week": "2026-W38",
      "title": "Ask the Tool, Don't Guess: Agent Tool Calls Hold Their Progress, and the Serving System Should Read It",
      "title_zh": "提取失败",
      "authors": [
        "Yipeng Liu",
        "Yingqiang Zhang",
        "Feifei Li",
        "Huanchen Zhang"
      ],
      "url": "http://arxiv.org/abs/2609.18849v1",
