      "id": "2609.18736",
      "direction_id": "agent-skills-harness",
      "direction_name": "Agent Skills 与 Harness",
      "week": "2026-W38",
      "title": "Clueing up LLMs with Tool-Augmented Deductive Reasoning",
      "title_zh": "提取失败",
      "authors": [
        "Rebecca Ansell",
        "Autumn Toney-Wails"
      ],
      "url": "http://arxiv.org/abs/2609.18736v1",
