      "id": "2609.29154",
      "direction_id": "agent-skills-harness",
      "direction_name": "Agent Skills 与 Harness",
      "week": "2026-W39",
      "title": "A Wrong Turn Does Not Ruin the Journey: Deviation-Guided Skill Self-Evolution for LLM Agents",
      "title_zh": "提取失败",
      "authors": [
        "Yichun Feng",
        "Jiawei Wang",
        "Haozhe Sun"
      ],
      "url": "http://arxiv.org/abs/2609.29154v1",
