      "title": "A Safety-Bounded SDC-to-MCP Gateway for Medical AI Agents",
      "title_zh": "提取失败",
      "authors": [
        "Bennet Gerlach",
        "Stefan Fischer"
      ],
      "url": "http://arxiv.org/abs/2609.31358v1",
