      "id": "2610.01348",
      "direction_id": "agent-skills-harness",
      "direction_name": "Agent Skills 与 Harness",
      "week": "2026-W40",
      "title": "Verify Claims, Not Scores: Evidence-Based Verification of Modular Agents",
      "title_zh": "提取失败",
      "authors": [
        "Ali Atiah Alzahrani"
      ],
      "url": "http://arxiv.org/abs/2610.01348v1",
