      "id": "2610.05943",
      "direction_id": "agent-skills-harness",
      "direction_name": "Agent Skills 与 Harness",
      "week": "2026-W41",
      "title": "Runaway Reaction: When Benign Skills Compose into Malicious Behavior",
      "title_zh": "提取失败",
      "authors": [
        "Zunlong Zhou",
        "Ziyuan Yang",
        "Mengyu Sun",
        "Yi Zhang"
      ],
      "url": "http://arxiv.org/abs/2610.05943v1",
