      "id": "2610.11899",
      "direction_id": "agent-skills-harness",
      "direction_name": "Agent Skills 与 Harness",
      "week": "2026-W41",
      "title": "Forms of LLM-Integrated Applications from LLM-Chats to Autonomous AI Agent System",
      "title_zh": "提取失败",
      "authors": [
        "Irene Weber"
      ],
      "url": "http://arxiv.org/abs/2610.11899v1",
