      "id": "2606.01857",
      "direction_id": "multi-agent-consistency",
      "direction_name": "多 Agent 交互与一致性",
      "week": "2026-W23",
      "title": "From Global Policies to Local Strategies: Multi-Objective Optimization of Resource-Specific Handover Policies",
      "title_zh": "从全局策略到局部策略：资源专属交接策略的多目标优化",
      "authors": [
        "Lukas Kirchdorfer",
        "Artemis Doumeni",
        "Han van der Aa",
        "Hugo A. López"
      ],
      "url": "http://arxiv.org/abs/2606.01857v1",
      "pdf_url": "https://arxiv.org/pdf/2606.01857v1",
