      "venue_type": "",
      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "大语言模型在高风险主张验证中存在幻觉与浅层推理缺陷，现有方法受单次检索、非结构化辩论动态限制。",
      "method": "提出PROClaim法庭式多智能体框架，集成专业角色与渐进RAG，结合证据协商、多法官聚合完成主张验证。",
      "contribution": "在Check-COVID基准零样本评测获81.7%准确率，证明结构化审议可有效缓解大语言模型系统偏差。",
