      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "大语言模型应用于医疗场景时易产生幻觉，常违规推荐已禁撤的药物，威胁临床决策安全。",
      "method": "基于单大模型骨干构建五智能体系统，通过事后对抗审计与多智能体反馈环降低医疗幻觉。",
      "contribution": "构建了对抗性临床禁药评测数据集，提出的方法可有效降低医疗幻觉错误率，提升临床安全性。",
      "limitations": "摘要未提及",
      "key_finding": "默认配置下所有测试模型都存在高幻觉率，该多智能体架构跨模型平均降低约53%的幻觉错误率。",
      "theme": "多智能体医疗安全",
      "method_family": "multi-agent coordination",
      "agent_setting": "multi-agent 临床问答",
      "control_mechanism": "通过事后对抗审计拦截危险输出，结合多智能体反馈循环验证大模型输出，降低幻觉提升医疗安全性。",
      "evaluation_environment": "自制临床多选题对抗数据集，评测指标含准确率、幻觉错误率HER、CF得分等",
      "evaluation_signal": "原生大模型普遍存在高幻觉错误率，提出方法跨模型降低约53%幻觉错误率，提升临床输出安全性。",
      "failure_mode": "大模型原生配置易输出符合训练模式但违规危险的医疗内容",
      "reliability_risk": "仅在小规模自制数据集测试，未在真实大规模临床场景验证落地有效性。",
      "industrial_relevance": "high",
      "read_priority": "medium",
