      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "针对高风险场景下，单个智能体产生的错误信息会通过多智能体交互传播，降低系统可靠性的问题展开研究。",
      "method": "在推理、知识、对齐三类任务中，向良性单智能体与多智能体系统注入基于意图的错误信息开展对照研究。",
      "contribution": "揭示了多智能体系统错误信息鲁棒性由底层模型、信息交互方式与决策聚合规则共同决定的规律。",
