      "title": "Can LLM Coding Agents Reason About Time Series?",
      "title_zh": "大语言模型编码智能体能否推理时间序列？",
      "authors": [
        "Filip Rechtorík",
        "Ondřej Dušek",
        "Zdeněk Kasner"
      ],
      "url": "http://arxiv.org/abs/2606.16545v1",
