      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "交互式环境中LLM智能体对提示词高度敏感，当前提示词工程仍为手动、任务特定流程，缺乏自动化优化方案。",
      "method": "提出基于环境回报引导的自动提示词优化框架，将流程分解为两个智能体模块，迭代优化提示并经环境验证。",
      "contribution": "提出无需更新模型权重的自动提示词优化框架，在基准任务显著提升性能，复杂任务实现大跨度性能突破。",
      "limitations": "摘要未提及",
      "key_finding": "在PutNext多步协调任务中，基线RobustCoTAgent成功率为0%，该方法用相同LLM达到最高72.5%的成功率，无需微调。",
      "theme": "自动提示优化",
      "method_family": "model steering",
      "agent_setting": "交互式游戏环境",
      "control_mechanism": "将观测到动作的流程分解为两个智能体模块，基于环境回报通过LLM进化循环迭代优化提示，经环境回滚验证修改。",
      "evaluation_environment": "BALROG基准的五个BabyAI任务，评测指标为任务成功率",
      "evaluation_signal": "在所有任务所有设置下性能均有一致提升，PutNext任务从基线0%成功率提升至该方法的最高72.5%成功率。",
      "failure_mode": "手动设计提示适配性差，复杂多步任务易性能低下",
      "reliability_risk": "需要多轮环境回滚与LLM调用，优化成本较高，未验证跨任务的泛化能力。",
