      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "研究多智能体大语言模型团队中，过程层面的协调控制（领导力）在哪些可测量条件下能产生表现增益。",
      "method": "将三类经典领导力风格实现为共享动作集上的显式控制器，结合行为特征分析，在多任务多模型下验证权变理论。",
      "contribution": "验证了多智能体LLM团队中领导力的权变效应，明确了协调控制获得恢复优势的三类边界条件。",
      "limitations": "摘要未提及",
      "key_finding": "仅满足特定边界时控制才有效，llama-4-scout社交任务中情景控制涨8pp，其余组合精度差均在1.3pp以内。",
      "theme": "多Agent协调控制",
      "method_family": "multi-agent coordination",
      "agent_setting": "multi-agent",
      "control_mechanism": "将经典领导力风格转化为共享动作集上的显式控制器，对多智能体团队实现过程级协调控制，验证其生效边界。",
      "evaluation_environment": "四类多智能体任务域、三类开放权重大语言模型，评测指标为准确率",
      "evaluation_signal": "对比不同控制器与基线的准确率差异，验证协调控制增益边界，多数场景下与基线精度差在1.3pp以内",
      "failure_mode": "初始轮错误共识锁定，无向交互无法自行修复，拉低团队表现",
      "reliability_risk": "仅在有限任务和模型上验证，未在复杂真实场景测试，结论通用性尚不明确",
      "industrial_relevance": "medium",
