      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有医疗错误检测纠正方法泛化能力差，难以适配未见数据集，无法满足医疗场景的安全要求。",
      "method": "提出多智能体框架MedGuards，分工完成错误检测定位纠正，用置信度引导仲裁机制解决分歧，无需额外训练基座模型。",
      "contribution": "提出MedGuards多智能体框架与新评估指标KPCS，在多语言医疗数据集上效果显著提升，开源代码方便复现。",
      "limitations": "摘要未提及",
