      "manual_tags": [],
      "problem": "现有多智能体路由依赖未经验证的间接代理衡量能力，恶意智能体可伪造能力植入后门，存在严重安全漏洞。",
      "method": "提出评估驱动的路由架构ANTAP，动态测试智能体真实能力，蒸馏为共享语义空间行为算子，推理时经非文本代数投影路由。",
      "contribution": "提出可抵御元数据攻击的语言防火墙路由机制，实验显示其对各类注入攻击的防御效果远优于现有基线。",
      "limitations": "摘要未提及",
      "key_finding": "对基于描述的注入攻击，ANTAP攻击成功率接近零，基线达67.3%以上；对自适应嵌入攻击，攻击成功率较基线降低20%。",
      "theme": "多Agent安全路由",
      "method_family": "unlearning/safety",
      "agent_setting": "multi-agent",
