      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有多LLM智能体辩论的多数投票范式依赖独立错误假设，LLM错误相关会系统性压制正确的少数意见",
      "method": "提出轻量元分类器Minority Sentinel，从辩论日志提取多维辩论指纹，训练LightGBM判断何时推翻多数投票",
      "contribution": "发现约四分之一分歧案例中少数答案正确，所提方法获稳定正净收益，证明翻转安全性比恢复量更重要",
      "limitations": "摘要未提及",
