      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "LLM智能体持久记忆的推理历史缺乏有效保护，易遭投毒攻击，现有各类防御机制均可被绕过。",
      "method": "提出针对推理记忆的投毒攻击FARMA，以及分层防御框架SENTINEL，通过多加权信号检测伪造推理。",
      "contribution": "提出新型推理记忆投毒攻击与对应防御方案，实验验证了攻击的破坏力和防御的有效性。",
      "limitations": "摘要未提及",
      "key_finding": "FARMA在基线条件下攻击成功率最高可达100%，可击败现有防御，SENTINEL可将其攻击成功率降至0%且无假阳性。",
      "theme": "智能体记忆安全",
      "method_family": "unlearning/safety",
      "agent_setting": "LLM智能体记忆场景",
      "control_mechanism": "提出分层防御流程SENTINEL，核心推理卫士通过五个加权信号分析推理条目，检测伪造以抵御投毒攻击。",
      "evaluation_environment": "多个不同大语言模型与智能体，评测指标为攻击成功率、假阳性",
      "evaluation_signal": "FARMA基线条件下攻击成功率最高达100%，可击败现有防御；SENTINEL可将成功率降至0%且无假阳性。",
