      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有LLM智能体评测基准多默认单语言设置，多语言性与智能体执行的交互缺乏充分探索，缺少对应评测基准。",
      "method": "构建涵盖5个领域共67个任务的多语言长视野职场工作流基准，提出结合三类评估方式的混合评测框架。",
      "contribution": "提出多语言长视野LLM智能体评测基准PolyWorkBench与混合评测框架，发现SOTA智能体在该场景性能显著下降。",
      "limitations": "摘要未提及",
      "key_finding": "多语言性会在LLM智能体的推理与执行步骤产生复合效应，使现有SOTA智能体性能相较单语言场景显著下降。",
      "theme": "智能体基准评测",
      "method_family": "evaluation/benchmark",
      "agent_setting": "tool-use",
      "control_mechanism": "提出结合结构评分、可执行验证与LLM语义评估的混合评测框架，用于全面评估多语言长视野智能体。",
