      "title": "Unveiling Complex Collective Behaviors from Simple Rewards",
      "title_zh": "从简单奖励中揭示复杂群体行为",
      "authors": [
        "Yize Mi",
        "Jianan Li",
        "Liang Li",
        "Shiyu Zhao"
      ],
      "url": "http://arxiv.org/abs/2607.12861v1",
      "pdf_url": "https://arxiv.org/pdf/2607.12861v1",
