      "theme": "智能体可靠性评估",
      "method_family": "agent harness",
      "agent_setting": "multi-agent/tool-use",
      "control_mechanism": "构建开源评估框架ProofAgent-Harness，从七个维度度量上下文质量，为智能体可靠性提供预检评估信号。",
      "evaluation_environment": "摘要未提及",
      "evaluation_signal": "验证上下文各维度质量与智能体对应行为结果的相关性，验证上下文得分对可靠性的预测有效性。",
