      "theme": "API调用智能体数据生成",
      "method_family": "skill generation",
      "agent_setting": "tool-use",
      "control_mechanism": "生成无需可执行环境的合成交互轨迹微调模型，引入LLM裁判过滤轨迹，保证数据质量以提升智能体性能。",
      "evaluation_environment": "AppWorld、OfficeBench基准测试",
      "evaluation_signal": "在涵盖信息检索与状态改变任务的两个基准上，使用合成数据微调的模型获得了显著性能提升。",
      "failure_mode": "摘要未提及",
