      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "临床多智能体诊断框架中，现有通信拓扑假设忽略语义漂移，其对诊断安全的负面影响缺乏定量研究。",
      "method": "将多智能体通信不确定性映射到BERT嵌入空间，提出基于图拉普拉斯分解的动态谱监测与代数连通性约束方法。",
      "contribution": "推翻了多智能体通信拓扑效率最优的假设，提出了保障临床多智能体诊断可靠性的拓扑约束方法。",
      "limitations": "摘要未提及",
      "key_finding": "高度聚类的枢纽型多智能体架构会产生51.81%的语义漂移方差放大，自主复合局部幻觉，阻碍全局共识，导致系统熵饱和。",
      "theme": "多Agent一致性",
      "method_family": "consistency detection",
      "agent_setting": "multi-agent",
      "control_mechanism": "通过动态谱监测通信拓扑，基于图拉普拉斯连续特征分解设置代数连通性下界，保障全局状态扩散，抑制语义漂移。",
