      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有多智能体系统仅支持阶段边界间通信，执行中发现的信息无法及时共享，难以处理长视界中互相依赖的子任务。",
      "method": "提出带线程、消息、提及等待三个原语的异步消息传递层AgentRadio，让智能体保持被动感知，无需打断当前任务。",
      "contribution": "提出支持执行阶段异步通信的AgentRadio，在长代码理解任务上大幅提升任务解决率，效果优于单智能体及现有基线。",
      "limitations": "摘要未提及",
      "key_finding": "四个经AgentRadio组织的智能体在SWE-Atlas QnA上达到62.1%任务解决率，性能增益随任务难度提升而增长。",
      "theme": "多智能体协作",
      "method_family": "multi-agent coordination",
      "agent_setting": "coding/multi-agent",
      "control_mechanism": "通过新增异步消息传递harness层，让智能体保持对同伴的被动感知，实现执行过程中的实时信息协调，不打断当前工作。",
      "evaluation_environment": "SWE-Atlas QnA生产代码库问答基准，评测指标为任务解决率",
