      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "多智能体产生错误输出后，现有研究多聚焦故障归因，缺乏自动从错误中恢复的修复机制",
      "method": "提出搜索框架MARS，将多智能体修复建模为蒙特卡洛树搜索，结合诊断引导与部分回滚降低token消耗",
      "contribution": "提出自动修复框架MARS，构建大规模多智能体修复基准StateMAS，实验证明性能显著优于现有SOTA",
      "limitations": "摘要未提及",
