      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "针对大语言模型智能体强化学习的稀疏奖励问题，以及现有自蒸馏方法对噪声敏感、忽略位置差异的缺陷。",
      "method": "提出持久一致性自蒸馏PCSD，基于教师偏好信号局部持久性生成token级自适应蒸馏权重，与GRPO联合优化。",
      "contribution": "提出PCSD方法，无需推理阶段额外技能，在多个基准测试中性能显著优于GRPO、SDAR等基线方法。",
      "limitations": "摘要未提及",
