        "Emmanuel Paul Kwesiga",
        "Anqi Peter Li",
        "Josephine Nanyonjo",
        "Aaditya Panchal",
        "Arshnoor Bhutani",
        "Nikhil Jaiswal",
        "Milit S. Patel",
        "Maximin Lange",
        "Leo Anthony Celi"
