      "title": "Abstract Event Causal Rules: Induction and Application",
      "title_zh": "抽象事件因果规则：归纳与应用",
      "authors": [
        "Ziwei Zheng",
        "Peiqiong Chen",
        "Bang Wang"
      ],
      "url": "http://arxiv.org/abs/2608.05205v1",
