      "title": "CAITLYN: Can LLM Agents Autonomously Synthesize Defenses against Emerging Injection Attacks?",
      "title_zh": "CAITLYN：大语言模型智能体能否自主合成针对新型注入攻击的防御？",
      "authors": [
        "Zi Liang",
        "Xiaoyu Xu",
        "Yanyun Wang",
        "Minxin Du",
        "Qingqing Ye",
        "Haibo Hu"
      ],
      "url": "http://arxiv.org/abs/2608.27990v1",
      "pdf_url": "https://arxiv.org/pdf/2608.27990v1",
