      "venue_url": "https://openreview.net/forum?id=NgJP9uJXvZ",
      "venue_confidence": "openreview",
      "venue_source": "openreview",
      "is_authority_venue": true,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有异构多智能体协作感知中，独立训练的模态转换器易产生模态特有伪协议分布，引发语义不一致与误差累积。",
      "method": "提出因果统一模态无关网络CauseCollab，用因果度量学习解耦语义与模态混杂因素，搭配上下文引导统一转换器保证一致性。",
      "contribution": "提出CauseCollab框架保证跨模态语义一致性，新增模态仅需训练少量参数，在公开数据集上达到SOTA性能。",
