      "id": "2610.11188",
      "direction_id": "multi-agent-consistency",
      "direction_name": "多 Agent 交互与一致性",
      "week": "2026-W41",
      "title": "What to Admit and How to Present: Governing Persistent Memory in LLM Agents",
      "title_zh": "提取失败",
      "authors": [
        "Chang Liu",
        "Deliang Ding"
      ],
      "url": "http://arxiv.org/abs/2610.11188v1",
