      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "基于MCP运行的LLM Agent动作空间扩展带来权力攫取风险，微小错误易被放大为灾难性安全故障。",
      "method": "提出服务端防御插件SafeMCP，基于内部世界模型前瞻推理实现双层防御，通过三阶段流程结合双可验证奖励强化学习训练。",
