      "title": "Progress-SQL: Improving Reinforcement Learning for Text-to-SQL via Progressive Rewards",
      "title_zh": "Progress-SQL：通过渐进式奖励改进Text-to-SQL的强化学习方法",
      "authors": [
        "Shihao Zhang",
        "Xiaoman Wang",
        "Yuan Liu",
        "Yunshi Lan",
        "Weining Qian"
      ],
      "url": "http://arxiv.org/abs/2606.06825v1",
