      "title": "PAEC: Position-Aware Entropy Calibration for LLM Reasoning in RLVR",
      "title_zh": "PAEC：面向RLVR中大语言模型推理的位置感知熵校准",
      "authors": [
        "Shumeng Yang",
        "Yisu Liu",
        "Jiayi Zheng",
        "Zhaohui Yang",
        "Linjing Li"
      ],
      "url": "http://arxiv.org/abs/2606.08543v1",
