      "title": "AIR: Adaptive Interleaved Reasoning with Code in MLLMs",
      "title_zh": "AIR：多模态大语言模型中基于代码的自适应交错推理",
      "authors": [
        "Cong Han",
        "Xiaohan Lan",
        "Haibo Qiu",
        "Yujie Zhong"
      ],
      "url": "http://arxiv.org/abs/2606.23678v1",
