      "title": "The Hitchhiker's Guide to Agentic AI: From Foundations to Systems",
      "title_zh": "《智能体AI搭车指南：从基础到系统》",
      "authors": [
        "Haggai Roitman"
      ],
      "url": "http://arxiv.org/abs/2606.24937v1",
