      "title": "dOPSD: On-Policy Self-Distillation for Diffusion Language Models",
      "title_zh": "dOPSD：面向扩散语言模型的同策略自蒸馏",
      "authors": [
        "Phuong Tuan Dat",
        "Qi Li",
        "Xinchao Wang"
      ],
      "url": "http://arxiv.org/abs/2607.04428v1",
