      "title": "Verifier-Based Reinforcement Fine-Tuning of Reasoning Models for Thermal Energy Storage Control",
      "title_zh": "面向储热控制的推理模型基于验证器的强化微调",
      "authors": [
        "Takumi Shioda",
        "Kohei Terashima",
        "Tatsuo Nagai"
      ],
      "url": "http://arxiv.org/abs/2607.12856v1",
      "pdf_url": "https://arxiv.org/pdf/2607.12856v1",
