      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "大语言模型开展基于语言的量化预测时，易产生幻觉与过度自信错误，缺乏对齐预测质量的可靠置信估计。",
      "method": "提出CARE-PPO强化学习框架，关联PPO微调与不确定性估计，采用置信对齐奖励，推理时复用评判器作为置信估计器。",
      "contribution": "在医疗、金融真实任务上验证性能，所得置信估计对齐度显著优于基线，跨域分布外泛化性好，可减少过拟合。",
      "limitations": "摘要未提及",
      "key_finding": "将训练得到的评判器复用为置信估计器，其置信对齐效果显著优于现有两类基线，跨域分布外场景仍保持性能优势。",
      "theme": "量化预测置信估计",
      "method_family": "policy optimization",
      "agent_setting": "非Agent论文",
      "control_mechanism": "设计与预测误差对齐的置信奖励，通过演员-评判器PPO强化学习微调，诱导模型生成可靠的置信估计。",
      "evaluation_environment": "医疗、金融领域两个真实任务，基于4B/8B规模Qwen-3模型评测",
      "evaluation_signal": "所得置信估计与预测质量的对齐度显著优于两类基线，跨域分布外场景性能保持优势，可减少任务特定过拟合。",
      "failure_mode": "预测幻觉、过度自信错误",
      "reliability_risk": "仅在医疗、金融两个领域任务验证，未测试更多通用场景，方法通用性未得到充分验证。",
      "industrial_relevance": "medium",
