      "title": "Digital Pantheon: Simulating and Auditing Coalition Formation with LLM Agents",
      "title_zh": "数字万神殿：基于LLM智能体的联盟形成模拟与审计",
      "authors": [
        "Dylan Van Mulders",
        "Matthias Bogaert",
        "Dirk Van den Poel"
      ],
      "url": "http://arxiv.org/abs/2607.15095v1",
      "pdf_url": "https://arxiv.org/pdf/2607.15095v1",
