      "title": "Debiasing Text-to-Image Evaluation via Implicit Cultural Alignment Reward Modeling",
      "title_zh": "通过隐式文化对齐奖励建模实现文生图评估去偏",
      "authors": [
        "Bo-An Chang",
        "Yu-Chih Chen"
      ],
      "url": "http://arxiv.org/abs/2607.15740v1",
      "pdf_url": "https://arxiv.org/pdf/2607.15740v1",
