      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有多轮智能体强化学习主流方法依赖独立完整轨迹采样，长视距任务中浪费预算，优质中间状态探索不足。",
      "method": "提出过程评分器引导的自适应树状展开PATR框架，基于过程反馈选择性分支、复用前缀、裁剪退化路径实现高效探索。",
      "contribution": "提出适配多轮RL的PATR框架，同等训练预算下提升探索效率，在基准测试中获得显著性能提升。",
      "limitations": "摘要未提及",
