      "title": "A Dual-Hypothesis Reasoning Framework for LLM Guardrails",
      "title_zh": "面向大语言模型护栏的双假设推理框架",
      "authors": [
        "Md Asiful Islam",
        "Mihai Surdeanu"
      ],
      "url": "http://arxiv.org/abs/2607.17575v1",
      "pdf_url": "https://arxiv.org/pdf/2607.17575v1",
