      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有RLVR仅适用于固有可验证领域，开放式任务的现有奖励方案存在偏差、能力瓶颈与额外推理成本。",
      "method": "提出基于任务变换的RLSVR训练范式，将开放式任务转为可验证代理环境自动生成奖励，实例化为多智能体自博弈环境SpyRL。",
      "contribution": "将基于RLVR的可扩展自提升扩展到非固有可验证领域，实验验证效果优于现有方案，开源了模型与代码。",
      "limitations": "摘要未提及",
      "key_finding": "基于任务变换的RLSVR在非可验证开放式任务上优于现有自提升方法，在可验证推理任务上也能获得一致性能提升。",
      "theme": "奖励学习",
      "method_family": "reward learning",
      "agent_setting": "multi-agent",
      "control_mechanism": "通过任务变换构造可自动生成完全自可验证奖励的代理环境，以奖励信号引导大语言模型自提升优化。",
      "evaluation_environment": "文本摘要、创意写作、数学推理任务",
      "evaluation_signal": "SpyRL在非可验证开放式任务上性能优于现有自提升方法，在可验证推理任务上可获得一致的性能增益。",
      "failure_mode": "摘要未提及",
      "reliability_risk": "方法依赖定制化任务变换设计，通用性有待验证，多智能体自博弈训练的整体成本较高。",
