      "venue_type": "",
      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "RLVR依赖稀疏最终奖励，缺乏步级决策信用信号，现有过程信号难以同时兼顾廉价与准确。",
      "method": "提出CAST方法，将游戏求解器的状态值变化转换为优势信号注入RLVR，仅需标量值即可实现从求解器的策略蒸馏。",
      "contribution": "提出的CAST方法在多类游戏和两个真实任务上性能超过所有基线，取得了最高的平均零样本性能。",
      "limitations": "摘要未提及",
