      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "多步语言模型智能体交互增长导致上下文成本过高，视觉文本压缩降本后，模态偏移会引发策略能力缺口。",
      "method": "提出两阶段跨模态智能体策略自蒸馏框架CAPS，用同模型的文本历史策略监督视觉分支，结合离线与在线自蒸馏。",
      "contribution": "验证了智能体策略缺口的存在，所提方法在多个基准实现性能提升，大幅降低智能体上下文存储成本。",
      "limitations": "摘要未提及",
