      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "现有无人机导航方法泛化适应性不足，现有LLM辅助导航智能体存在记忆、规划与交互机制缺陷",
      "method": "提出LAPF框架，整合感知、记忆、规划、动作模块形成闭环认知架构，结合推理动态修正航点决策",
      "contribution": "提出整合多模块的LLM智能体导航框架，实验证明其路径效率高、稳定性好，性能显著优于基线",
      "limitations": "摘要未提及",
      "key_finding": "LAPF在开阔场和障碍物注入场景分别实现97.1%和98.1%路径效率，两种场景均为零钳位事件，远优于CoT提示",
      "theme": "LLM智能体导航",
      "method_family": "agent harness",
      "agent_setting": "tool-use",
      "control_mechanism": "整合感知、记忆、规划、动作模块形成闭环认知架构，基于环境反馈修正航点，为检测风险匹配校正动作",
