      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "RLVR任务级反馈稀疏，OPD忽略轨迹正确性性能受限，现有二者结合方案引入额外超参数与权衡。",
      "method": "提出OPDVR方法，基于轨迹正确性重构OPD隐式奖励，通过ReLU门控对齐蒸馏信号与任务成功，无缝结合OPD与RLVR。",
      "contribution": "提出无额外超参数的OPDVR方法，可适配任意策略梯度算法，六个推理基准上性能稳定优于标准OPD。",
      "limitations": "摘要未提及",
