      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "仅依赖终点结果的稀疏奖励下，小模型长时域交互智能体RL存在信号匮乏、策略漂移导致的性能瓶颈。",
      "method": "提出CANOPY（覆盖锚定同策略强化学习）协议，扩展同任务探索获取信号，保持KL锚定同策略更新，测试时放大交互预算。",
      "contribution": "提出解决纯结果RL瓶颈的极简训练协议，在两个编码基准取得SOTA，将开源完整训练技术栈。",
      "limitations": "摘要未提及",
      "key_finding": "仅结果RL的性能瓶颈源于信号匮乏与策略漂移而非方法本身，该方案让Qwen3.5-9B在SWE-bench Verified提分16.6。",
      "theme": "长时域智能体训练",
      "method_family": "policy optimization",
      "agent_setting": "coding",
      "control_mechanism": "通过扩展同任务探索解决信号匮乏，引入KL锚定同策略更新约束策略漂移，测试时放大交互预算提效。",
      "evaluation_environment": "AppWorld、SWE-bench Verified长时域交互编码基准",
      "evaluation_signal": "Qwen3-14B登顶2026年2月AppWorld公开榜，Qwen3.5-9B在SWE-bench Verified提升16.6个百分点。",
      "failure_mode": "信号匮乏、策略漂移导致仅结果RL提前触达性能瓶颈",
      "reliability_risk": "该方法需要扩大交互探索预算，训练成本较高，对于小模型落地存在一定成本压力。",
      "industrial_relevance": "high",
