      "venue_url": "",
      "venue_confidence": "",
      "venue_source": "",
      "is_authority_venue": false,
      "ingest_source": "",
      "manual_reason": "",
      "manual_tags": [],
      "problem": "RLVR依赖粗粒度结果奖励，对推理过程引导不足，现有方法存在依赖专用模型、要求师生推理模式一致的约束。",
      "method": "提出Cliff奖励塑形策略，利用现成大语言模型识别推理轨迹的首个错误，将其转换为token级优势反馈。",
      "contribution": "提出简单通用有效的Cliff方法，在12个场景中稳定提升推理性能，优于在线策略蒸馏15%、标准GRPO 7%。",
      "limitations": "摘要未提及",
