      "manual_reason": "",
      "manual_tags": [],
      "problem": "GRPO等基于结果奖励的大语言推理RL方法仅依赖最终答案，缺乏中间步骤反馈，长轨迹下奖励稀疏问题严重。",
      "method": "从多rollout正确轨迹中聚类得到推理中间共识节点，构造过程奖励ConsensusPR，整合进GRPO类算法。",
      "contribution": "提出新基准ConsensusBench与过程奖励ConsensusPR，配套三个评估指标，实验验证效果优于GRPO类方法。",
      "limitations": "摘要未提及",
      "key_finding": "基于共识节点的过程奖励可有效缓解长推理轨迹奖励稀疏，在多个推理数据集上性能稳定优于GRPO类方法。",
      "theme": "推理奖励稠密化",
      "method_family": "reward learning",
      "agent_setting": "非Agent论文",
      "control_mechanism": "基于共识节点构造稠密过程奖励，融入GRPO类强化学习算法，缓解奖励稀疏，引导大模型生成正确推理过程。",
      "evaluation_environment": "AIME 2024、AIME 2025、GSM8K、MATH-500、ConsensusBench，评测指标为Acc、NCR、TPN",
      "evaluation_signal": "在多个公开数学推理数据集与自建ConsensusBench上，所提方法的最终答案准确率稳定优于GRPO类基准方法。",
      "failure_mode": "长推理轨迹下最终奖励稀疏，缺乏中间步骤反馈导致推理性能不足",
      "reliability_risk": "依赖规则提取共识节点与构造奖励，在开放域非规则任务上的泛化性存在不确定性。",
