      "title": "Reasoning-Preserving Fine-Tuning of Post-RL LLMs with Null-Basis LoRA",
      "title_zh": "提取失败",
      "authors": [
        "Wenzhi Fang",
        "Nicholas Tzou",
        "Lazar Valkov",
        "Srinivas Chappidi"
      ],
      "url": "http://arxiv.org/abs/2609.25618v1",
